(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ha"] = {"ui":{"skip":"Tsallake zuwa abubuwan shafin","back":"← Koma zuwa AI-gile","lang.button":"Harshe: {name}","lang.dialog":"Zaɓi harshe","lang.search":"Nemi harsuna","lang.none":"Babu harshen da ya dace","lang.notYet":"Ba a fassara {name} ba tukuna","theme.aria":"Canza yanayi: haske, duhu ko baƙi","theme.toLight":"Koma yanayin haske","theme.toDark":"Koma yanayin duhu","theme.toBlack":"Koma yanayin baƙi (baƙi na gaske, mai sauƙi ga allon OLED)","words.underline":"Ja layi a ƙarƙashin waɗannan kalmomi a shafin","words.underlineHelp":"Ku kai linzami kan kalma mai ɗigo ko ku taɓa ta don ganin ma'anarta.","words.col.todo":"Katunan da aka zaɓa don yanzu: ƙungiya za ta fara da waɗannan a gaba.","words.col.doing":"Wani AI yana aiki a kan wannan kati yanzu.","words.col.review":"Wani AI ya gama aikin; wani kuma yana duba shi kafin ya iso gare ka.","words.col.verify":"Ana jiran ka: gwada shi ka faɗa idan yana aiki.","words.col.team":"Bayananka ko amsoshinka, suna jiran ƙungiya ta ɗauka.","words.col.done":"An gama kuma an amince.","index.title":"AI-gile: ƙungiyar AI ɗinku ta masu shirye-shirye, a allo ɗaya","index.description":"AI-gile allon kanban ne don ƙungiyoyin AI masu rubuta lamba. Suna aiki yayin da kuke barci; ku kuwa kuna samun ɗan tarin abubuwa don yanke shawara, gwadawa da karɓa.","hero.logoAlt":"Alamar allon AI-gile","hero.h1.html":"Ƙungiyar AI ɗinku ta masu shirye-shirye, a allo&nbsp;ɗaya.","hero.alpha":"🐣 Pre-alpha a rufe","hero.alphaTitle":"Na farko ne kuma ba a gama ba: na gode da gwadawa!","hero.lede":"Suna ginawa yayin da kuke barci. Kuna farkawa zuwa ɗan tarin kaɗan: 'yan tambayoyi, 'yan abubuwan gwadawa, lu'u-lu'u mai shuɗi ɗaya ko biyu. Danna, karɓa, ku koma kofi ɗinku.","dl.windows":"Manhajar Windows","dl.browser":"Gudanar da shi a browser","dl.messenger":"📱 Messenger don wayarku","dl.soon":"Nan ba da daɗewa ba","dl.notify":"🔔 Ku sanar da ni idan ya buɗe","dl.notifySmall":"Alpha ko beta","hero.secondary":"Agile, amma ƙungiyar ba ta taɓa buƙatar kofin tsaye na taro ba. (Duk da haka suna yin taron.)","pitch.h2":"AI-gile da kalmomi kamar yadda kuke so","pitch.lede":"Zaɓi tsayi, daga kalma ɗaya zuwa 144. Kowane tsayi bayaninsa ne na kansa, wanda aka rubuta don wannan girman. Ja maɓallin zamiya ko ku yi amfani da maɓallan kibiya.","pitch.rangeLabel":"Tsayi cikin kalmomi","pitch.dice":"🎲 wani sigar","pitch.words.one":"kalma {n}","pitch.words.other":"kalmomi {n}","pitch.letters.one":"harafi {n}","pitch.letters.other":"haruffa {n}","pitch.chars.one":"alama {n}","pitch.chars.other":"alamomi {n}","count.line.html.one":"kati {n} a allo yanzu","count.line.html.other":"kati {n} a allo yanzu","people.humans.html.one":"👥 mutum {n}","people.humans.html.other":"👥 mutane {n}","people.agents.html.one":"🤖 wakili {n}","people.agents.html.other":"🤖 wakilai {n}","people.working.html.one":"⚡ {n} na aiki yanzu","people.working.html.other":"⚡ {n} na aiki yanzu","pre.title":"AI-gile: ana gina wani abu","pre.description":"Ana gina wani abu a nan. Allo inda ƙungiyoyin AI ke gina abin da ka nema, kuma suna koya maka yayin da suke aiki. A yanzu pre-alpha ce a rufe tare da abokai.","pre.h1":"Ana gina wani abu a nan. 🤫","pre.line":"Allo inda ƙungiyoyin AI ke gina abin da ka nema, kuma suna koya maka yayin da suke aiki. A yanzu pre-alpha ce a rufe tare da abokai.","pre.btn":"🔔 Ku sanar da ni idan ya buɗe","pre.peek":"Bayan gilashi: ainihin allon, kai tsaye. Kowane kati layi ne mai launi.","pre.peekFake":"Bayan gilashi: haka allo yake idan ana aiki.","pre.night":"🌙 Mai tsaron dare ne ke jagoranci · 😴 mutumin yana hutawa","features.aria":"Abin da yake yi","f.pile.h":"Tari ɗaya a gare ku","f.pile.html":"<b>Gare ku</b> yana ɗauke da duk abin da ke jiran ku, a kowane aiki: tambayoyi, abubuwan gwadawa, ayyukan da mutum kaɗai zai iya yi. Layinku yana faɗin abin da ke gaba da tsawon lokacin da zai ɗauka.","f.sleep.h":"Ƙungiyoyi masu aiki yayin da kuke barci","f.sleep.p":"Kowane aiki yana da jagora da ƙungiyar wakilan AI. Ku yi sharhi a kan kati sai ƙungiyar ta farka, ta yi aikin, ta mayar da shi da matakan da gajiyayyen mutum zai iya bi.","f.tester.h":"Mai gwajin AI yana dubawa tukuna","f.tester.p":"Kafin wani abu ya zo gare ku, mai gwaji yana bin matakai a kwafin manhajar kuma yana nuna abin da ya gani, da hoton allo. Ku duba waɗanda suka yi nasara ku karɓa da danna ɗaya.","f.proof.h":"Shaida, ba alkawari ba","f.proof.p":"Kowace miƙawa tana nuna abin da ya canza: fayilolin, bambancin, hotunan allo. Ba sai kun buɗe kowace manhaja don ganin an gama ba.","f.chat.h":"Ku yi hira da jagororinku","f.chat.p":"Ginshiƙi irin na Discord: alama ɗaya ga kowane aiki, lu'u-lu'u masu shuɗi ga abin da ke buƙatar ku. Ku aika wa jagora ra'ayi; zai mayar da shi kati da shiri, tare da maɓallin ✅ Go.","f.tidy.h":"Yana tsara kansa","f.tidy.p":"Katuna masu alaƙa suna haɗuwa wuri ɗaya, ana gyara taken da suka ruɗe, kuma duba token yana sa lamba ta zama marar nauyi. Ƙarancin abubuwan da za a sauya tsakaninsu, ƙarancin tunani.","f.private.h":"Naku ne, a kwamfutarku","f.private.li1":"Allon yana aiki a injin ɗinku kuma yana amsa muku kaɗai.","f.private.li2":"DM na sirri tsakanin mutane an ɓoye su daga ƙarshe zuwa ƙarshe.","f.private.li3":"Babu asusu, babu masu bin diddigi, babu kuki.","f.lang.h":"A cikin harshenku","f.lang.p":"Harsuna sama da 120, daga Dutch, Welsh da Japananci zuwa na 'yan fashin teku, Yoda da Klingon, da saurin komawa Turanci don kalmomin sana'a.","f.service.h":"Daga ra'ayi zuwa sabis na gaske","f.service.p":"Ka gina wani abu da AI da mutane ke amfani da shi yanzu? Yi masa alama a matsayin sabis kuma allon zai taimaka maka ka gudanar da shi da kyau: binciken uptime, shafin matsayi na jama'a, matsaloli da rubutaccen bita, canje-canje da ke buƙatar Go, ajiyar tsaro da ake dubawa kowace rana. Taimako yana koya maka kowane mataki yayin da kake tafiya.","msgr.h2":"AI-gile Messenger: ƙungiyarku a aljihunku","msgr.p1":"Ku yi magana da ƙungiyarku ta AI ba tare da buɗe allo ba. Ku yi hira da jagororin ayyukanku da abokanku, ku ga matakan gwajin kati ku amsa su, duka daga wayarku.","msgr.p2":"Don haɗa ta, ku duba lambar QR a kan allonku. Karon farko? Hirar demo mai daɗi za ta nuna muku yadda komai yake.","msgr.when":"Android da farko, sannan sigar yanar gizo don wayoyi da iPhone.","msgr.who":"Jagoran aikinku","msgr.b1":"Gyaran yanayin duhu ya shirya. Kuna son matakan gwajin?","msgr.b2":"Eh, don Allah!","msgr.b3":"1. Buɗe Saiti. 2. Zaɓi Duhu. Yana da kyau kuwa?","tl.aria":"Jerin lokaci daga tattaunawar farko zuwa taswirar gaba","tl.h2":"Daga tattaunawar farko zuwa abin da ke gaba","tl.lede":"Kwanaki da lokuta na gaske, a yankin lokacinku. Bayan yau shiri ne, ba tare da alƙawarin kwanan wata ba.","tl.today":"Yau","tl.planned":"a shirye","tl.doing":"ana yi","tl.cards.one":"kati {n}","tl.cards.other":"katuna {n}","join.h2":"Ku shiga","join.lede":"Wani mutum mai gemu, ɗan baƙon hali, mai AuDHD da wasu gwagwarmaya da lafiyar ƙwaƙwalwa, tare da wakilai masu haƙuri da yawa ne ke gina AI-gile. Na sirri ne a yanzu, a alpha a rufe tare da abokai. Kuna son gwadawa idan ya buɗe?","join.btn":"Yi rijistar sha'awa","join.small":"Za mu rubuto muku imel, ba wani abu ba","footer.tag":"AI-gile. Babu masu bin diddigi, babu kuki, babu kofin tsaye na taro.","footer.licence":"Lasisin kasuwanci","footer.status":"Matsayi","footer.privacy":"Abin da muke ajiyewa","footer.thanks":"Kira albarkacin ChilledChat","form.sending":"Ana aikawa…","form.failed":"Hakan bai yi aiki ba: ku sake gwadawa daga baya.","form.offline":"Ba a iya isa ga AI-gile ba: ku sake gwadawa daga baya.","form.keep":"Muna amfani da wannan ne kawai don mu ba ku amsa, sannan mu goge shi. Babu masu bin diddigi, babu kuki.","form.keepLink":"Abin da muke ajiyewa","interest.title":"AI-gile: ku sanar da ni idan alpha ya buɗe","interest.description":"Ku bar imel ɗinku don jin lokacin da alpha ko beta na AI-gile a rufe zai buɗe.","interest.h1":"🔔 Ku sanar da ni idan ya buɗe","interest.lede":"AI-gile yana pre-alpha a rufe. Ku bar imel ɗinku za mu rubuto sau ɗaya, idan akwai wuri a gare ku.","interest.email":"Imel ɗinku","interest.which":"Wane gwaji?","interest.alpha":"Alpha a rufe: da wuri, mai tsauri, sauye-sauye da yawa","interest.beta":"Beta: ya fi tsayawa, daga baya","interest.both":"Duk ɗaya, wanda ya fara zuwa","interest.submit":"Saka ni cikin jerin","interest.thanks":"Na gode! Kuna cikin jerin.","licence.title":"AI-gile: lasisin kasuwanci","licence.description":"Kuna amfani da AI-gile a kasuwancinku? Ku nemi lasisin kasuwanci kyauta.","licence.h1":"📜 Lasisin kasuwanci","licence.lede":"Kuna amfani da AI-gile a wurin aiki? Ku gaya mana ko ku wane ne da abin da kuke yi. Idan yana yin alheri, lasisin kyauta ne.","licence.company":"Kamfani","licence.website":"Shafin yanar gizo","licence.what":"Abin da kuke yi","licence.how":"Yadda yake taimakon duniya","licence.email":"Imel","licence.submit":"Nema","licence.thanks":"Na gode! Za mu amsa ta imel.","status.title":"Matsayin AI-gile","status.h1":"Matsayin AI-gile","status.quiet":"Komai lafiya","status.intro":"Shin AI-gile yana aiki yanzu? Wannan shafi yana duba gidan yanar gizo, raba allo, kira da saukarwa duk bayan minti 5.","status.up":"Yana aiki (ya amsa cikin {ms} ms)","status.slow":"Bai amsa dubawar ƙarshe ba, ana sake gwadawa","status.down":"Ya faɗi: bai amsa dubawa biyu na ƙarshe ba","status.svc.web":"Gidan yanar gizo","status.svc.web.offers":"Wannan shafin: menene AI-gile, da fom ɗin sha'awa","status.svc.boards":"Raba allo","status.svc.boards.offers":"Alluna na jama'a, saƙonni tsakanin abokai da gayyata","status.svc.calls":"Kira","status.svc.calls.offers":"Murya, bidiyo da raba fuskar na'ura a AI-gile","status.svc.download":"Saukarwa","status.svc.download.offers":"Mai shigarwa na Windows da hanyoyin gayyata","status.checking":"Ana dubawa…","status.offline":"Ba a iya isa ga sabis ɗin matsayi yanzu (ana sake gwadawa)","status.updated":"an sabunta {ago}","status.justNow":"yanzu-yanzu","status.min":"mintuna {n} da suka wuce","status.hours":"awa {n} da ta wuce","status.days":"kwana {n} da suka wuce","privacy.title":"AI-gile: abin da muke ajiyewa","privacy.h1":"Abin da muke ajiyewa","privacy.lede":"A taƙaice: abin da kuka aiko mana kawai, kuma ba na dogon lokaci ba.","privacy.only":"Abin da kuka aiko mana kawai: abin da kuka rubuta a fom, kamar imel ɗinku. Babu wani abu kuma game da ku.","privacy.sealed":"Ana rufe shi da hatimi don kada sabarmu ta iya karanta shi: a cikin browser ɗinku kafin ya tafi (a tsohon browser, a lokacin da ya iso). Allonmu kaɗai ne zai iya buɗe shi.","privacy.server":"Ana goge shi daga sabar da zarar ya isa allonmu. Duk abin da ya rage a can bayan kwana 30 ana goge shi ko ta yaya.","privacy.board":"Muna ajiye shi a allonmu ne kawai har sai mun ba ku amsa, sannan mu goge shi a can ma.","privacy.none":"Babu masu bin diddigi, babu kuki, babu nazarin bayanai.","privacy.local":"Harshenku da zaɓinku na haske ko duhu suna zama a cikin browser ɗinku. Ba a taɓa aiko mana da su ba.","privacy.ask":"Kuna so a goge shi da wuri? Ku amsa imel ɗinmu ku faɗa mana.","live.h2":"Kalli yadda ake gina shi, kai tsaye","live.caption":"An ɓoye kowane kati: kana ganin siffar aikin, ba kalmomin ba.","live.watching.one":"kai tsaye: {n} na kallo","live.watching.other":"kai tsaye: {n} na kallo","live.last.now":"An motsa katin ƙarshe yanzu-yanzu","live.last.min.one":"An motsa katin ƙarshe mintuna {n} da suka wuce","live.last.min.other":"An motsa katin ƙarshe mintuna {n} da suka wuce","live.last.hour.one":"An motsa katin ƙarshe awa {n} da ta wuce","live.last.hour.other":"An motsa katin ƙarshe awanni {n} da suka wuce","live.last.day.one":"An motsa katin ƙarshe rana {n} da ta wuce","live.last.day.other":"An motsa katin ƙarshe kwanaki {n} da suka wuce","live.offline":"Allon kai tsaye yana hutawa kaɗan. Ka sake dubawa nan ba da jimawa ba.","live.cols":"Backlog|A yi|Ana yi|Ƙungiya na dubawa|Don a gwada|Don ƙungiya|An gama"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Mutummutumai.","Wakilta."]},{"n":2,"texts":["Mutummutumi kanban.","Wakilai tsararru.","Ra'ayoyi, gini."]},{"n":3,"texts":["Kanban don mutummutumai.","Ra'ayoyi su zama fasali.","Kanban na wakilai, kyauta."]},{"n":5,"texts":["Allon kanban da wakilai ke tafiyarwa.","Ku rubuta kati. Wakilai su gina.","Kyauta, na gida, ɗan wasa."]},{"n":8,"texts":["Allon kanban kyauta inda wakilan AI ke aiki.","Rubuta ra'ayi. Wakilai su gina shi. Ku karɓa.","Agile don mutum ɗaya da mutummutumai masu haƙuri da yawa."]},{"n":13,"texts":["Allon kanban a kwamfutarku inda wakilan AI ke ɗaukar katunan aiki.","Rubuta ra'ayi. Ƙungiyar wakilai ta gina shi. Mai gwaji ya duba.","Kyauta, babu asusu ko masu bin diddigi: allo, wasu mutummutumai, kuma ku ne shugaba."]},{"n":21,"texts":["AI-gile allon kanban ne don aiki da wakilan AI masu rubuta lamba. Su ke ɗaukar katunan; ku kuwa kuna gwadawa da karɓa.","Kowane aiki yana samun jagora da ƙungiyar wakilan AI. Ku yi sharhi a kowane kati sai ƙungiyar ta fara aiki.","Allon ayyuka na kai, kyauta, mai aiki a kwamfutarku. Ma'aikata mutummutumai ne. Wanda ke cewa eh, ku ne."]},{"n":34,"texts":["Kuna sa ra'ayoyi a allo. Ƙungiyar wakilan AI tana mayar da su fasalolin da ke aiki, tana gwada su, ta mayar muku da su tare da matakan gwadawa. Babu abin da ake ƙirgawa an gama sai kun faɗa.","AI-gile allon kanban ne na gida da Rich ya gina da taimako mai yawa daga wakilan da yake gudanarwa yanzu. Kyauta ne, yana aiki a kwamfutarku, ana raba shi da abokai, ba a sayarwa ba.","Ku yi tunanin allon kanban na yau da kullum, da ginshiƙai daga Backlog zuwa An gama, amma wakilan AI ne ke ɗaukar katunan. Suna ba da rahoton ci gaba, suna tambaya idan sun makale, kuma kullum suna jiran yardarku."]},{"n":55,"texts":["AI-gile allon kanban ne inda ƙungiyar ta kunshi wakilan AI. Kowane aiki yana da jagora da ke tsara aikin da masu taimako da ke gina shi. Idan fasali ya shirya, mai gwajin AI yana gwada shi ya ɗauki hoton allo, sannan ya isa tarinku. Ku karɓa, ko ku yi sharhi su sake yi.","Ya fara ne a matsayin hanyar mutum ɗaya na bin zaman rubuta lamba na AI da yawa lokaci guda, sannan ya girma ya zama allo na gaske. Yana aiki a injin ɗinku, ba ya buƙatar asusu, kuma ba shi da masu bin diddigi. Haka kuma ba a gama ba, don haka ku sa ran gefuna masu tsauri da wani abin mamaki.","Ga sigar gaskiya. Har yanzu dole ne ku kasance da ra'ayoyin, kuma dole ne ku duba sakamakon. Abin da AI-gile ke yi shi ne duk abin da ke tsakanin: yana tsara katunan, yana tashe wakilin da ya dace idan kun yi sharhi, yana nuna daidai abin da ya canza, kuma yana tara komai a ɗan gajeren tari a gare ku."]},{"n":89,"texts":["AI-gile allon kanban ne kyauta da kuke gudanarwa a kwamfutarku. Maimakon mutane, kowane aiki yana da ƙungiyar wakilan AI: jagora da ke mayar da ra'ayoyinku kati da shiri, da masu taimako da ke ɗaukar katunan bisa fifiko. Idan an gina wani abu, mai gwajin AI yana bin matakan gwaji ya nuna muku abin da ya gani. Sannan yana jira a tari ɗaya mai suna Gare ku. Kuna karɓa, ko ku yi sharhi ƙungiyar ta sake gwadawa. Babu abin da ke isa An gama ba tare da ku ba.","Akwai wasu siffofi da ba za ku yi tsammani ba. Tsaron dare yana cika ginshiƙin A yi yayin da kuke barci, yana zaɓar katunan da ba sa buƙatar amsarku. Na'urar ƙidayar token tana nuna yawan da wakilai suka yi amfani da shi yau da wannan mako, kuma Yanayin Babu Token yana gaya musu su daina kashewa. Kuna iya aika saƙo ga abokai, kuma saƙonnin sirri an ɓoye su daga ƙarshe zuwa ƙarshe. Allon yana magana da harsuna kusan 120, ciki har da Dutch, Flemish, na 'yan fashin teku da Klingon. Babu ɗaya daga cikinsu da ke da farashi, kuma babu wanda ke ƙoƙarin sayar muku.","AI-gile ƙaramin aiki ne na kai, ba kamfani ba. Rich yana son kula da ayyukan rubuta lamba na AI da yawa ba tare da buɗe kowace manhaja ya duba ba, don haka shi da wakilai suka gina allo don haka, sannan suka yi amfani da allon wajen gina sauran. Yana pre-alpha a rufe, ma'ana yana aiki, galibi, ga ɗimbin abokai. Babu shafin farashi, babu jaridar imel, babu shirin girma. Idan ya yi kama da mai amfani, kuna iya neman gwadawa idan ya buɗe kaɗan."]},{"n":144,"texts":["AI-gile allon kanban ne don mutum ɗaya da wakilan AI da yawa. Yana aiki a kwamfutarku kuma kyauta ne gaba ɗaya. Kuna ƙara ayyuka, kuma kowane aiki yana samun jagora da ƙaramar ƙungiya. Kuna hira da jagora, kamar Discord, kuna kwatanta ra'ayi; jagora yana mayar da shi kati da shiri, sannan yana jiran ku danna Go. Ƙungiyar tana aiki ta cikin katunan bisa fifiko, da layin umarni mai sauƙi da aka yi wa samfuran harshe. Kafin wani abu ya dawo gare ku, mai gwajin AI yana bin matakai a kwafin manhajar ya haɗa hoton allo. Aikin da aka gama yana isa tarinku tare da fayilolin da suka canza da bambancin. Kuna karɓa, ko ku bar sharhi ƙungiyar ta farka ta sake gwadawa. Ku kaɗai ne za ku iya matsar da kati zuwa An gama.","Kwana ɗaya da AI-gile, kusan. Da yamma kuna barin sharhi kaɗan: wannan maɓalli yana wurin da bai dace ba, ya kamata a jera wancan jerin, za mu iya samun yanayin duhu. Kuna kwanciya barci. Wakilai suna karanta sharhin, suna yin sauye-sauyen, suna gwada su, suna mayar muku. Idan A yi ya ƙare, tsaron dare yana cika shi daga backlog da katunan da ba sa buƙatar amsarku. Da safe akwai tari ɗaya gajere: tambayoyi biyu da abubuwan gwadawa kaɗan, kowanne da matakan da mai barci zai iya bi da hoton allo na yana aiki. Kuna danna, kuna karɓar masu kyau, kuna mayar da sauran. Na'urar ƙidayar token tana nuna abin da aka yi amfani da shi, kuma Yanayin Babu Token yana nan don makonni masu sauƙi. Sannan kuna karin kumallo, wanda wakilai ba za su iya taimako a kai ba tukuna.","Da farko, abin da AI-gile ba shi ba. Ba kamfanin farawa ba ne, ba na sayarwa ba, kuma babu wanda ke tattara bayananku. Allo ne kyauta da ke aiki a kwamfutarku, babu asusu, babu masu bin diddigi, babu kuki. Abin da yake shi ne: wuri ɗaya mai tsabta don ganin duk ayyukan rubuta lamba na AI a lokaci guda, da ƙungiyar wakilai suna yin katunan, ku kuma kuna yanke shawara. Yana haɗa katunan masu alaƙa, yana gyara taken da suka ruɗe, kuma yana lura da yadda lamba take zama marar nauyi. Yana magana da harsuna kusan 120, daga Dutch da Flemish zuwa na 'yan fashin teku da Klingon. Abokai za su iya aika wa juna saƙo, a sirri kuma a ɓoye. Rich da wakilai masu haƙuri da yawa ne suka gina shi, galibi suna amfani da shi da kansa. Yana pre-alpha a rufe, don haka akwai tsauri a wurare. Idan ya yi kama da nishaɗi, ku nemi da ladabi kuma wataƙila ku shiga da wuri."]}],"quips":{"1":"Kalma ɗaya. Jarumtaka. Wataƙila ta wuce kima.","3":"Kalmomi uku. Sun fi gaskiya fiye da yawancin shafukan samfura.","8":"Kalmomi takwas. Har yanzu sun fi taro gajarta.","21":"Tsawon kalmomi maki na labari ne, ta hanya. Ai haka ne.","55":"Kalmomi hamsin da biyar. An gama katuna biyu yayin da kuke karanta wannan.","144":"Wannan shi ne dogon. Babu 233. Wakilai sun tafi barci."}},"timeline":{"first-idea.name":"Ra'ayin farko","first-idea.line":"Tattaunawa ta farko, kafin wata lamba ta wanzu.","first-board.name":"Allo na farko","first-board.line":"Allon da ke bin diddigin ginin kansa: katuna, ginshiƙai, ja da sauke, ayyuka.","team-roles.name":"Ƙungiya da matsayi","team-roles.line":"Bayanan wakilai, samfuran ƙungiya, wurare da wanda ke yin me.","install.name":"Shigarwa da fitarwa","install.line":"Zip da aboki zai iya shigarwa, sabuntawa kai-tsaye, hanyoyi da komawa baya.","usage-saver.name":"Tanadin amfani","usage-saver.line":"Auna abin da gudanarwa ke ci, kiyaye lamba marar nauyi, ajiye iyakarku.","friends.name":"Abokai da rabawa","friends.line":"DM na sirri, na'urar isar da saƙo a ɓoye, gayyata, matsayi da ayyukan da aka raba.","languages.name":"Harsuna","languages.line":"Kowane rubutun allo a cikin fayil na harshe, Dutch da Flemish na farko.","ai-tester.name":"Mai gwajin AI","ai-tester.line":"Mai gwaji yana duba kowace miƙawa tukuna kuma yana nuna abin da ya gani.","website.name":"Shafin yanar gizo","website.line":"aigile.lol, gwaji na farko da wannan jerin lokaci.","streaming.name":"Hira da yawo","streaming.line":"Discord, Twitch, OBS, yanayin mai yawo, GIF da emoji.","no-ai.name":"Fitowar babu AI","no-ai.line":"Allo ga masu rubuta lamba babu AI, da allunan jama'a.","night-watch.name":"Tsaron dare","night-watch.line":"Mai tsaro da Scrum Master suna kiyaye ƙungiyoyi a kan aiki yayin da kuke barci.","p-more.name":"Duk sauran","p-more.line":"Ƙananan ra'ayoyi da ke jiran lokacinsu.","p-android.name":"Waya da Android","p-android.line":"Isa allonku daga waya, sannan manhajar Android ta asali.","p-release.name":"Alpha da bayansa","p-release.line":"Alpha a rufe, shafin kai-tsaye, sannan beta.","p-languages.name":"Ƙarin harsuna","p-languages.line":"Harsuna 130, da yanayin nutsewa ga masu koyo.","p-engines.name":"Ƙarin injunan AI","p-engines.line":"Zaɓi Claude, Codex, Gemini, Copilot ko Cursor ga kowane wakili.","p-pro.name":"Aikin ƙwararru","p-pro.line":"Alamomin haɗari, ƙofofin haɗawa, katunan faruwa da shingaye.","p-self.name":"Kula da ku","p-self.line":"Yanayin gajiya, tunatarwar kula da kai da 4:20.","p-servers.name":"Sabobi da girma","p-servers.line":"Saitunan sabar na duniya, matsayi da tsara girma.","p-livestream.name":"Ƙarin yawo","p-livestream.line":"Hirar Twitch, emoji na kai da kallon kai-tsaye na jama'a."},"words":{"button":"📖 Kalmomin sana'a","h":"📖 Bayanin kalmomi","intro":"Horarwa kyauta cikin harshe mai sauƙi: kowace kalma da za ku haɗu da ita daga ra'ayi na farko zuwa sabis da mutane ke dogara da shi, da Agile, gini, kiyaye shi lafiya da aiki da AI a hanya.","search":"Nemo kalma…","none":"Babu kalmar da ta dace da wannan.","close":"Rufe","count":{"one":"kalma {count}","other":"kalmomi {count}"},"groups":[{"id":"idea","name":"💡 Ra'ayi da bincike"},{"id":"plan","name":"🗺️ Tsara aiki"},{"id":"agile","name":"🔁 Hanyoyin aiki na Agile"},{"id":"build","name":"🛠️ Gina shi"},{"id":"test","name":"🧪 Gwaji da inganci"},{"id":"change","name":"🔀 Canza shi lafiya"},{"id":"run","name":"🛎️ Gudanar da sabis"},{"id":"sec","name":"🔒 Tsaro da sirri"},{"id":"ai","name":"🤖 Aiki tare da AI"},{"id":"money","name":"💰 Kuɗi da lasisi"}],"list":[{"id":"discovery","g":"idea","word":"Gano","text":"Matakin farko na gano wace matsala ta cancanci a warware ta kuma ga wane, kafin a gina komai.","also":["matakin gano","discovery","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Bayanin matsala","text":"Jumla ɗaya ko biyu da ke cewa wane ne ke da matsala, menene ita da dalilin da yasa take da muhimmanci, don kowa ya yi nufi ɗaya.","also":["bayanan matsala","problem statement","problem statements"]},{"id":"user","g":"idea","word":"Mai amfani","text":"Mutumin da ke amfani da abin da kuke ginawa. Bukatunsa ne dalilin aikin.","also":["masu amfani","user","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Mai ruwa da tsaki","text":"Duk wanda ya damu da yadda aikin zai kasance ko aikin ya shafe shi, kamar masu biyan kuɗinsa, masu amfani da shi ko masu tallafa masa.","also":["masu ruwa da tsaki","stakeholder","stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"Mutumin ƙirƙira amma na gaske da ke wakiltar nau'in mai amfani ɗaya, don ƙungiya ta tambaya “shin Sam zai ga wannan mai sauƙi?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"Binciken masu amfani","text":"Magana da kallon mutane na gaske don a koyi abin da suke buƙata, maimakon a yi zato.","also":["tattaunawa da masu amfani","user research","user interviews"]},{"id":"journey","g":"idea","word":"Tafiyar mai amfani","text":"Matakan da mutum ke bi don ya kammala wani abu, daga jin labarinsa na farko har ƙarshe, har da waje da samfurinku. Zana su yana nuna inda suke makalewa.","also":["tafiye-tafiyen mai amfani","user journey","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Wurin wahala","text":"Abin da ke ɓata wa mutane rai ko ke rage musu gudu a yau. Kyawawan samfura suna kawar da wuraren wahala.","also":["wuraren wahala","pain point","pain points"]},{"id":"assumption","g":"idea","word":"Zato","text":"Abin da kuke gaskatawa amma ba ku tabbatar ba tukuna. Rubuta zato yana nuna abin da za a fara gwadawa.","also":["zato-zato","assumption","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hasashe","text":"Mafi kyawun zato da kuke shirin tabbatarwa, tare da abin da kuke tsammani zai faru, kamar “mutane za su yi rajista idan wata na farko kyauta ne”.","also":["hasashe-hasashe","hypothesis","hypotheses"]},{"id":"experiment","g":"idea","word":"Gwajin bincike","text":"Ƙaramin gwaji da aka tsara don koyon ko ra'ayi yana aiki, kafin a yi kasada da yawa a kansa.","also":["experiment","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Gwajin yiwuwa (PoC)","text":"Gwaji cikin sauri don ganin ko ra'ayi zai yiwu ko kaɗan. Yawanci ana watsar da shi da zarar kun sami amsa.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Samfurin farko","text":"Samfurin farko na samfurin, sau da yawa hotuna masu dannawa, don gwada ra'ayin a kan mutane kafin a gina shi yadda ya kamata.","also":["prototype","prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Zane mai sauƙi na allo da ke nuna inda abubuwa suke, ba tare da launuka ko ainihin abun ciki ba.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Cikakken hoto na yadda allo zai kasance, da ainihin launuka da rubutu, amma babu abin da ke aiki tukuna.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Dalilin kasuwanci","text":"Dalilan yin aiki: nawa yake kashewa, abin da yake kawowa ko ajiyewa, da haɗarin.","also":["business case","business cases"]},{"id":"feasibility","g":"idea","word":"Yiwuwa","text":"Ko za a iya gina wani abu a kula da shi da lokaci, kuɗi da ƙwarewar da kuke da su.","also":["mai yiwuwa","feasibility"]},{"id":"outcome","g":"idea","word":"Sakamako","text":"Canjin da kuke so ga mutane, kamar ƙarancin alƙawuran da aka rasa. Yana da muhimmanci fiye da yawan abin da kuka gina.","also":["sakamakon","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Abin da aka samar","text":"Wani abu da ƙungiya ke yi, kamar sabon allo ko rahoto. Yin sa ba yana nufin yana taimaka wa kowa ba.","also":["output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Ma'aunin nasara","text":"Lamba da ke gaya muku ko aikin ya cimma abin da aka yi shi saboda shi, kamar ƙarin mutane da ke kammala odarsu.","also":["ma'aunan nasara","success metric","success metrics"]},{"id":"kpi","g":"idea","word":"Manyan alamomin aiki (KPI)","text":"Muhimmiyar lamba da kuke kallo don ganin ko abubuwa suna tafiya daidai, kamar rajista a kowane mako.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Manufofi da sakamako masu muhimmanci (OKR)","text":"Hanyar saita buri: manufa tana cewa abin da kuke so, kuma ƴan sakamako masu muhimmanci su ne lambobin da ke nuna kun isa.","also":["OKR","OKRs","objectives and key results"]},{"id":"product","g":"plan","word":"Samfur","text":"Abin da ake ginawa ana kula da shi saboda masu amfani da shi, kamar manhaja, gidan yanar gizo ko kayan aiki.","also":["samfura","product","products"],"noTip":1},{"id":"vision","g":"plan","word":"Hangen samfur","text":"Taƙaitaccen bayani na wanda samfur yake taimaka wa da inda yake nufa a nan gaba.","also":["bayanin hangen nesa","vision","vision statement"]},{"id":"po","g":"plan","word":"Mai samfur (PO)","text":"Wanda ke yanke shawarar abin da za a gina da kuma jerinsa, don ƙungiya ta yi aiki kan abu mafi muhimmanci koyaushe. A AI-gile wannan kai ne.","also":["PO","masu samfur","product owner","product owners"]},{"id":"pm","g":"plan","word":"Manajan samfur (PM)","text":"Wanda ke kula da alkiblar samfur: waɗanne matsaloli yake warwarewa, ga wane da me ya sa. PM kuma na iya nufin manajan aiki, don haka a duba wanne ne.","also":["PM","manajojin samfur","product manager","product managers"]},{"id":"projmgr","g":"plan","word":"Manajan aiki","text":"Wanda ke tabbatar da aiki a kan lokaci da kasafin kuɗi, yana bin diddigin wanda zai yi me da kuma lokacin da.","also":["manajojin aiki","project manager","project managers"]},{"id":"roadmap","g":"plan","word":"Taswirar hanya","text":"Shirin ƙiyasi na abin da ke zuwa a cikin watanni masu zuwa, bisa tsari. Yana nuna alkibla, ba ainihin kwanaki ba, kuma yana canjawa yayin da kuke koyo.","also":["taswirori","roadmap","roadmaps"]},{"id":"milestone","g":"plan","word":"Matsayi mai muhimmanci","text":"Wani matsayi a aiki da ya dace a yi masa alama, kamar “sigar farko ta fita” ko “masu amfani 100”.","also":["milestone","milestones"]},{"id":"mvp","g":"plan","word":"Mafi ƙarancin samfur mai amfani (MVP)","text":"Mafi ƙanƙantar sigar samfur da har yanzu take da amfani ga mutane na gaske, don ku koya daga gare su da wuri.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Buƙata","text":"Abin da dole ne samfurin da aka gama ya yi ko ya zama.","also":["buƙatu","requirement","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Iyakar aiki","text":"Abin da ke cikin aikin kuma, daidai da muhimmanci, abin da ba ya ciki.","also":["cikin iyaka","wajen iyaka","scope","in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Ƙaruwar iyaka","text":"Idan ana ƙara abubuwa a aiki kaɗan-kaɗan, ba tare da wani ya amince da ƙarin lokaci ko kuɗi ba, har aikin ba ya ƙarewa.","also":["scope creep","feature creep"]},{"id":"feature","g":"plan","word":"Siffa","text":"Abu ɗaya da samfur zai iya yi wa mutane, kamar “sake saita kalmar sirrinku”.","also":["siffofi","feature","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Babban guntun aiki, mai girma da yawa ga lokaci ɗaya, don haka ana raba shi zuwa ƙananan katuna.","also":["epics"]},{"id":"story","g":"plan","word":"Labarin mai amfani","text":"Ƙaramin guntun aiki da aka rubuta daga ɓangaren mai amfani: “A matsayina na mai siyayya, ina so in adana kwandona, don in gama daga baya.” Yana fara tattaunawa kan abin da za a gina.","also":["labaran masu amfani","user story","user stories"]},{"id":"ac","g":"plan","word":"Sharuɗɗan karɓa (AC)","text":"Binciken da kati ɗaya dole ne ya ci don a ƙidaya shi an gama, wanda aka amince da shi kafin aiki ya fara, kamar “kwandon yana nan bayan na fita na koma ciki”.","also":["AC","acceptance criteria"]},{"id":"task","g":"plan","word":"Ɗawainiya","text":"Aiki guda ɗaya da ake bukatar yi, sau da yawa ƙaramin mataki na babban labari.","also":["ɗawainiya-ɗawainiya","task","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Tikiti","text":"Wata kalma ce ga kati: guntun aiki ɗaya ko buƙata ɗaya, da ake bi daga farko zuwa ƙarshe.","also":["tikiti-tikiti","ticket","tickets"]},{"id":"priority","g":"plan","word":"Fifiko","text":"Yadda wani abu yake da muhimmanci ko gaggawa idan aka kwatanta da kowane abu, don aiki mafi muhimmanci ya fara.","also":["fifiko-fifiko","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Tsara fifiko","text":"Jera aiki bisa muhimmanci. Hanya ta gama-gari ita ce MoSCoW: Dole (Must), Ya kamata (Should), Zai yiwu (Could), Ba a wannan karon ba (Won't).","also":["prioritisation","MoSCoW"]},{"id":"estimate","g":"plan","word":"Ƙiyasi","text":"Mafi kyawun zato na girman ko tsawon aiki. Zato ne, ba alkawari ba.","also":["ƙiyasi-ƙiyasi","estimate","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Maki na labari","text":"Hanyar zaton girman aiki ta kwatanta katuna da juna (“kusan ninki biyu na wancan”) maimakon sa'o'i. Ba don kwatanta ƙungiyoyi ba ne.","also":["story point","story points"]},{"id":"tshirt","g":"plan","word":"Girman riga","text":"Zaton girman aiki a matsayin S, M, L ko XL. Mai sauri kuma ya isa don tsarawa na farko.","also":["t-shirt sizing","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Wasa don ƙiyasi: kowa yana nuna katin girma a lokaci ɗaya, sai mafi girma da mafi ƙanƙanta su yi bayani.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dogaro","text":"Idan wani guntun aiki ba zai iya farawa ko ƙarewa ba sai wani ya yi.","also":["dogaro-dogaro","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Cikas","text":"Duk abin da ke hana aiki ci gaba a yanzu, kamar amsar da ta ɓace ko kayan aiki da ya karye.","also":["cikas-cikas","blocker","blockers"]},{"id":"deadline","g":"plan","word":"Wa'adi","text":"Ranar da dole a gama wani abu.","also":["wa'adodi","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Abin da za a ba da","text":"Wani abu na zahiri da aikin ke samarwa ya miƙa, kamar shafi mai aiki ko rahoto.","also":["deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Hasashen lokaci","text":"Hasashen abin da zai iya faruwa, kamar lokacin da za a gama aiki, bisa abin da kuka sani zuwa yanzu.","also":["forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Ma'auni","text":"Duk abin da kuke aunawa kuna bi diddigi a kan lokaci, kamar ziyarar shafi ko tsawon lokacin gyara.","also":["ma'aunai","metric","metrics"]},{"id":"feedback","g":"plan","word":"Ra'ayin mutane","text":"Abin da mutane ke gaya muku game da aikinku, mai kyau da marar kyau. Samun sa da wuri akai-akai shi ne zuciyar Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Jerin jira na ra'ayoyi da aikin da ba a tsara su ba tukuna, mafi muhimmanci a sama. Ba a yin aiki a kan komai a can sai ya koma A yi."},{"id":"sprint","g":"agile","word":"Sprint","text":"Gajeren lokaci kayyadadde na aiki (yawanci mako ɗaya ko biyu, ba fiye da wata ɗaya ba) da buri da kuma katunan da aka amince da su za a gama.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Taƙaitaccen taron yau da kullun: abin da kowane memba na ƙungiya ya yi, abin da zai yi na gaba, da abin da ke hana shi. A Scrum ana kiransa daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Hanyar aiki inda katuna ke tafiya a ginshiƙan allo (kamar A yi, Ana yi, An gama) kuma ƙungiya tana iyakance nawa ake yi a lokaci ɗaya, don aiki ya ci gaba da gudana."},{"id":"wip","g":"agile","word":"Iyakar WIP","text":"WIP gajeren suna ne na work in progress. Iyakar WIP ita ce mafi yawan katunan da ginshiƙi ya kamata ya ɗauka a lokaci ɗaya, don ƙungiya ta gama abubuwa kafin ta fara wasu.","also":["WIP"]},{"id":"dod","g":"agile","word":"Ma'anar An gama","text":"Gajeren jerin ƙungiyar na abin da “an gama” ke nufi, kamar an gwada kuma an bayyana, kafin a miƙa maka kati. Tagwayenta, Ma'anar Shirye, tana faɗin lokacin da kati ya isa a fara shi.","also":["Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"Waiwaye na yau da kullun kan yadda ƙungiya ke aiki, don a amince da abu ɗaya ko biyu da za a inganta a gaba. Gajeren suna na retrospective. A AI-gile retro yana ba da shawarar canji a hanyoyin aikin ƙungiya, kuma ku ce Go ko Ba tukuna.","also":["retros","retrospective","waiwaye"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Kowa ya taru: mutane da yawa suna barin sauran aiki don gyara abu ɗaya na gaggawa tare har sai an gama. A AI-gile kowace ƙungiya tana taimakawa a aiki ɗaya, sauran ayyuka kuma suna jira a lokacin.","also":["swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"A Scrum, wanda ke taimaka wa ƙungiya ta yi aiki da kyau: yana kawar da abin da ke hana su, yana kiyaye tarurruka kan hanya yana koyar da kyawawan halaye, ba tare da yin wa kowa umarni ba. A AI-gile Lead Scrum Master yana gano katunan da suka makale, yana tunatar da ƙungiyoyi yana kuma tuna muku abin da ke jira, a kowane aiki.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Hanyar aiki da ƙananan matakai: gina kaɗan, nuna sakamako na gaske akai-akai, koyo daga abin da mutane ke faɗa a canja shiri yayin tafiya, maimakon a tsara komai tun da farko.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Sanarwar Agile","text":"Gajeren bayani da masu yin software suka rubuta a 2001. Yana sa mutane, sakamako masu aiki, aiki kusa da abokan ciniki da amsa canji gaba da manyan tsare-tsare da takardun aiki.","also":["Agile Manifesto","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Tsohuwar hanyar aiki: a tsara komai, sannan a gina duka, sannan a gwada duka, mataki bayan mataki. Canje-canje a ƙarshe suna da wahala da tsada.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Zagaye","text":"Zagaye ɗaya na gina wani abu, dubawa da inganta shi. Aikin Agile jerin waɗannan ne, kuma sprint nau'i ɗaya ne.","also":["zagaye-zagaye","iteration","iterations"]},{"id":"increment","g":"agile","word":"Ƙari","text":"Sabon guntu mai aiki da ake ƙarawa a samfur a sprint ko zagayen aiki, wanda ya dace da abin da ke akwai.","also":["increment","increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Shahararriyar hanyar aiki ta Agile: ƙaramar ƙungiya tana aiki a gajerun sprints zuwa buri, da ayyuka kayyadaddu da ƴan tarurruka na yau da kullun don tsarawa, dubawa da inganta."},{"id":"scrumteam","g":"agile","word":"Ƙungiyar Scrum","text":"Ƙaramar ƙungiyar da ke aiki a Scrum: mai samfur, Scrum Master da masu ginawa.","also":["ƙungiyoyin Scrum","Scrum team","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Taron Scrum","text":"Tarurrukan yau da kullun a Scrum: tsara sprint, daily scrum, nazarin sprint da retro. Mutane da yawa suna kiransu ceremonies.","also":["tarurruka","ceremonies","Scrum ceremonies","Scrum events"]},{"id":"sprintplan","g":"agile","word":"Tsara sprint","text":"Taron da ake yi a farkon sprint inda ƙungiya ke amincewa da dalilin sprint, katunan da za a ɗauka da yadda za a fara.","also":["taron tsarawa","planning meeting","sprint planning"]},{"id":"sprintgoal","g":"agile","word":"Burin sprint","text":"Jumla ɗaya da ke cewa abin da sprint yake yi. Ƙananan ayyuka na iya canjawa a hanya, matuƙar an cimma burin.","also":["sprint goal","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Katunan da aka zaɓa don sprint na yanzu, tare da shirin ƙungiya na yin su.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Jerin samfur (Product backlog)","text":"Cikakken jerin abubuwan da za a iya ginawa don samfur, mafi muhimmanci a sama. Yana ci gaba da canjawa yayin da kuke koyo.","also":["product backlog","product backlogs","jerin samfur"]},{"id":"productgoal","g":"agile","word":"Burin samfur","text":"Babban sakamakon da samfur ke aiki zuwa gare shi, wanda ke taimaka wa ƙungiya zaɓar abin da za ta yi na gaba.","also":["product goal","product goals"]},{"id":"refinement","g":"agile","word":"Gyaran backlog","text":"Duba backlog akai-akai don tsabtace, raba, jera da ƙara cikakken bayani a katuna, don su kasance a shirye a ɗauka. Ana kuma kiran shi backlog grooming.","also":["backlog grooming","backlog refinement","refinement"]},{"id":"sprintreview","g":"agile","word":"Nazarin sprint","text":"Taro a ƙarshen sprint inda ƙungiya ke nuna abin da ta gama kuma ta ji ra'ayin mutane, don yanke shawarar abin da zai biyo baya.","also":["sprint review","sprint reviews"]},{"id":"demo","g":"agile","word":"Nunin aiki","text":"Nuna aikin da aka gama yana aiki, kai tsaye, ga mutanen da suka nema.","also":["demo","demos","nuni"],"noTip":1},{"id":"timebox","g":"agile","word":"Lokaci kayyadadde","text":"Wani adadin lokaci kayyadadde don wani abu. Idan ya ƙare, ana tsayawa, ko da ba a gama komai ba.","also":["timebox","timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Gudun ƙungiya (velocity)","text":"Yawan aikin da ƙungiya ke gamawa a sprint yawanci, ana amfani da shi don tsara nawa za a ɗauka a gaba. Ba maki ba ne na yadda mutane ke ƙoƙari.","also":["velocity","team velocity","gudun ƙungiya"]},{"id":"capacity","g":"agile","word":"Ƙarfin aiki","text":"Yawan aikin da ƙungiya za ta iya ɗauka a wani lokaci, bayan hutu da sauran ayyuka.","noTip":1},{"id":"burndown","g":"agile","word":"Taswirar ragowar aiki (Burndown)","text":"Taswira ta ragowar aiki a sprint tana raguwa rana da rana. Idan layin ya tsaya daram, wani abu ya makale.","also":["burndown","burn-down chart","burndown chart"]},{"id":"burnup","g":"agile","word":"Taswirar aikin da aka gama (Burnup)","text":"Taswira ta aikin da aka gama yana ƙaruwa a kan lokaci, kusa da jimillar da aka tsara, don ku ga lokacin da za ku isa.","also":["burnup","burn-up chart","burnup chart"]},{"id":"kanbanboard","g":"agile","word":"Allon Kanban","text":"Allon kansa: ginshiƙi ga kowane mataki na aiki, tare da katuna suna tafiya a cikinsu.","also":["Kanban boards","Kanban board"]},{"id":"pullsys","g":"agile","word":"Tsarin jawowa (Pull system)","text":"Hanyar aiki inda sabon aiki ke farawa ne kawai idan wani yana da sarari ya ɗauka, maimakon a tura shi kan wanda ya riga ya cika.","also":["pull-based","pull system"]},{"id":"flow","g":"agile","word":"Kwararar aiki (Flow)","text":"Yadda aiki ke tafiya a kan allo cikin sauƙi. Kyakkyawan gudana yana nufin katuna suna ci gaba da motsi maimakon taruwa.","also":["flow of work","flow"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lokacin jira (Lead time)","text":"Tsawon lokacin da ake ɗauka daga lokacin da wani ya nemi wani abu har a gama shi.","also":["lead time","lead times"]},{"id":"cycletime","g":"agile","word":"Lokacin zagaye (Cycle time)","text":"Tsawon lokacin da kati ke ɗauka daga lokacin da aiki ya fara a kansa da gaske har a gama shi.","also":["cycle time","cycle times"]},{"id":"throughput","g":"agile","word":"Yawan abin da aka gama (Throughput)","text":"Katuna nawa ake gamawa a mako, ko a kowane lokaci kayyadadde.","also":["throughput","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Maƙogwaro (Bottleneck)","text":"Mataki ɗaya inda aiki ke taruwa yana rage gudun duk abin da ke bayansa, kamar kunkuntar wuyan kwalba.","also":["bottleneck","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Layin allo (Swimlane)","text":"Jere a faɗin allo da ke haɗa katuna iri ɗaya, kamar aiki na gaggawa ko katunan ƙungiya ɗaya.","also":["swimlane","swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Hanyar aiki da ke yanke ɓarna (duk abin da ba ya taimaka wa abokin ciniki) tana kuma sa aiki ya ci gaba da gudana."},{"id":"waste","g":"agile","word":"Ɓarna","text":"A Lean, duk abin da ke ɗaukar ƙoƙari amma ba ya taimaka wa abokin ciniki, kamar jira, sake yi ko gina abubuwan da babu wanda ke amfani da su.","noTip":1},{"id":"kaizen","g":"agile","word":"Ci gaba da ingantawa","text":"Samun ƙarin kyau a kowane lokaci ta ƙananan canje-canje na yau da kullun, sannan a duba ko sun taimaka. Retro hanya ɗaya ce. Ana kuma kiran shi kaizen.","also":["kaizen","continuous improvement"]},{"id":"selforg","g":"agile","word":"Ƙungiya mai tsara kanta","text":"Ƙungiyar da ke yanke shawara da kanta yadda za ta yi aikin, maimakon a gaya mata mataki-mataki.","also":["self-organising team","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Ƙungiya mai ƙwarewa iri-iri","text":"Ƙungiyar da ke da duk ƙwarewar da take buƙata don kammala aikin da kanta, kamar zane, gini da gwaji.","also":["cross-functional team","cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"Ɗan gajeren bincike mai lokaci kayyadadde don amsa tambaya kafin a himmatu ga ainihin aikin.","also":["spikes"]},{"id":"rework","g":"agile","word":"Sake yin aiki","text":"Sake yin aiki saboda bai yi daidai ba a karon farko.","also":["rework","reworked"]},{"id":"safe","g":"agile","word":"Agile mai girma (SAFe)","text":"Hanyoyin amfani da Agile a ƙungiyoyi da yawa a babbar ƙungiya. SAFe (Scaled Agile Framework) misali ne sananne.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Babban fayil ɗin lamba na aiki da cikakken tarihin commits. Yana iya kasancewa a kwamfutarku, a GitHub, ko duka biyu.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Layin aiki na daban a cikin lamba, don a yi canje-canje ba tare da taɓa babbar sigar ba.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Hoton lamba da aka adana, tare da gajeren bayanin abin da ya canja. Kullum za a iya komawa ɗaya.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Aika hotunan da kuka adana (commits) daga wannan kwamfuta zuwa kwafin da aka raba a kan layi, kamar GitHub, don a ajiye su kuma wasu su samu."},{"id":"merge","g":"build","word":"Merge","text":"Haɗa canje-canje daga branch ɗaya zuwa wani, yawanci komawa cikin babbar sigar."},{"id":"pr","g":"build","word":"Pull request","text":"Neman a duba canje-canjen branch a haɗa su cikin babbar sigar. Wasu shafuka suna kiransa merge request.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Tsara lamba ba tare da canja abin da take yi ba: ƙananan fayiloli, sunaye masu haske, ƙarancin maimaitawa."},{"id":"bug","g":"build","word":"Bug","text":"Wani abu da ba ya aiki yadda ya kamata.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Bitar abokin aiki","text":"Ido na biyu: wani ba marubuci ba yana duba aikin kafin ya isa gare ku, don ƙarancin kurakurai su wuce. A AI-gile wani AI yana duba kowane kati.","also":["peer review","code review"]},{"id":"code","g":"build","word":"Lamba","text":"Rubutattun umarni da ke gaya wa kwamfuta abin da za ta yi. Ana kuma kiran shi source code.","also":["lambar tushe","code","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Harshen shirye-shirye","text":"Harshe don rubuta lamba, kamar JavaScript, Python ko Java. Daban-daban sun dace da ayyuka daban-daban.","also":["harsunan shirye-shirye","programming language","programming languages"]},{"id":"developer","g":"build","word":"Mai haɓaka (dev)","text":"Wanda ke rubutawa da canza lamba. Ana kuma kiran shi mai shirya manhaja ko injiniyan software.","also":["masu haɓaka","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Manhaja (software)","text":"Shirye-shiryen da ke aiki a kwamfutoci da wayoyi, ba na'urorin kansu ba (hardware).","noTip":1},{"id":"app","g":"build","word":"Manhaja (app)","text":"Gajeren suna na application: shirin da mutane ke amfani da shi don yin wani abu, a waya, kwamfuta ko burauza.","also":["manhajoji","app","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Manhajar yanar gizo","text":"Manhajar da ke aiki a burauza, don haka babu abin da za a sanya.","also":["manhajojin yanar gizo","web app","web apps","web application"]},{"id":"frontend","g":"build","word":"Gaban manhaja (Front end)","text":"Ɓangaren manhaja da kuke gani kuna dannawa: allon, maɓallai da kalmomi, sau da yawa a burauzarku.","also":["front end","front-end","frontend"]},{"id":"backend","g":"build","word":"Bayan manhaja (Back end)","text":"Ɓangaren manhaja na bayan fage da ke adana bayanai yana yin aiki idan kun danna wani abu, kamar duba kalmar sirrinku.","also":["back end","back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Aiki a kan gaba da baya na manhaja duka.","also":["full-stack"]},{"id":"ui","g":"build","word":"Mu'amalar mai amfani (UI)","text":"Abin da mutum ke gani yana amfani da shi a allo: tsari, maɓallai, jerin zaɓi da rubutu.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"Ƙwarewar mai amfani (UX)","text":"Yadda ake ji wajen amfani da wani abu: mai sauƙi, bayyananne kuma mai daɗi, ko mai rikitarwa da jinkiri.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Isa ga kowa (a11y)","text":"Sa abubuwa su kasance masu amfani ga kowa, har da mutanen da ba sa gani da kyau, ba sa iya amfani da linzamin kwamfuta ko suke amfani da mai karanta allo.","also":["a11y","accessibility"]},{"id":"responsive","g":"build","word":"Zane mai daidaitawa","text":"Sa shafuka su dace su yi aiki da kyau a kowane girman allo, daga waya zuwa babban na'ura mai saka idanu.","also":["responsive design"]},{"id":"designsys","g":"build","word":"Tsarin zane","text":"Kayan haɗin gwiwa na launuka, rubutu, maɓallai da ƙa'idoji, don kowane allo ya yi kama kuma ya yi aiki iri ɗaya.","also":["design systems","design system"]},{"id":"architecture","g":"build","word":"Tsarin gini (Architecture)","text":"Cikakken surar tsari: menene manyan sassansa da yadda suke magana da juna."},{"id":"database","g":"build","word":"Ma'ajiyar bayanai (DB)","text":"Wurin ajiyar bayanai da aka tsara, kamar ƙaƙƙarfan takardar lissafi da manhaja za ta iya karantawa ta canza.","also":["database","databases","DB","ma'ajiyar bayanai"]},{"id":"schema","g":"build","word":"Tsarin ma'ajiyar bayanai","text":"Tsarin ma'ajiyar bayanai: waɗanne tebura na bayanai take da su da abin da ke shiga kowanne.","also":["schema","database schema"]},{"id":"sql","g":"build","word":"SQL","text":"Gajeren suna na structured query language: harshen da ake amfani da shi don tambayar ma'ajiyar bayanai da yawa ko canza su.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Bayanai","text":"Bayanin da kwamfuta ke adanawa, kamar sunaye, oda ko saituna.","also":["dataset","datasets","data"],"noTip":1},{"id":"server","g":"build","word":"Sabar","text":"Kwamfutar da ke a kunne koyaushe tana amsa buƙatu daga wasu kwamfutoci, kamar aika shafin yanar gizo idan kun ziyarce shi.","also":["sabobi","server","servers"]},{"id":"client","g":"build","word":"Abokin amfani (Client)","text":"Ɓangaren da ke nema, yawanci burauzarku ko manhajarku, yana magana da sabar. A kasuwanci kuma yana nufin abokin ciniki kawai.","also":["client","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Gajeren suna na application programming interface: jerin buƙatun da shiri ɗaya zai iya yi wa wani, kamar tambayar sabis na yanayi hasashen yau.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Abu ɗaya a jerin API: adireshin yanar gizo da shiri zai iya kira don samu ko aika wani abu.","also":["endpoints"]},{"id":"integration","g":"build","word":"Haɗa tsare-tsare","text":"Haɗa tsari biyu don su yi aiki tare, kamar shagonku yana aika oda zuwa manhajar lissafinku.","also":["integration","integrations","haɗin kai"]},{"id":"webhook","g":"build","word":"Webhook","text":"Saƙon da wani tsari ke aika wa wani da kansa da zarar wani abu ya faru, kamar “an karɓi biyan kuɗi”.","also":["webhooks"]},{"id":"library","g":"build","word":"Ɗakin karatu (Library)","text":"Lamba da aka riga aka shirya wadda wani ya rubuta da za ku sake amfani da ita maimakon ku rubuta da kanku.","also":["ɗakunan karatu","library","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Tsarin da aka shirya don gina manhaja wanda ke yanke yawancin yadda aka shimfiɗa lamba, kamar ƙashin gida da kuke cikawa.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Kayan haɓaka software (SDK)","text":"Akwatin kayan aiki, lamba da misalai don gina software don dandamali ko sabis ɗaya.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Dogaron software","text":"Ɗakin karatu ko kayan aiki da lambarku ke buƙata don aiki. Ci gaba da sabunta su yana da muhimmanci don tsaro.","also":["software dependency","software dependencies"]},{"id":"package","g":"build","word":"Fakiti","text":"Tarin lamba da aka shirya da za ku iya sanyawa ku yi amfani da ita a aiki.","also":["fakitoci","package","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Mai sarrafa fakiti","text":"Kayan aiki da ke ɗauko da sabunta fakitin da lambarku ta dogara da su. npm ɗaya ne gama-gari.","also":["package manager","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Kayan aiki mafi amfani wajen adana tarihin canje-canjen lamba, a matsayin commits da branches."},{"id":"github","g":"build","word":"GitHub","text":"Gidan yanar gizo da ke adana repos na Git a kan layi, don ƙungiyoyi su raba lamba, su duba canje-canje su bi diddigin aiki."},{"id":"vcs","g":"build","word":"Sarrafa sigogi","text":"Adana cikakken tarihin kowane canji a fayiloli, don ku ga wanda ya canza me kuma ku koma baya idan ana buƙata. Git yana yin haka.","also":["version control","source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Yin cikakken kwafin repo naku, da tarihinsa, a kwamfutarku.","also":["cloned","cloning","clone"]},{"id":"pull","g":"build","word":"Pull","text":"Ɗauko sabbin commits daga kwafin da aka raba (kamar GitHub) zuwa kwamfutarku. Akasin push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"Ainihin sigar lamba da kowa ke aiki daga gare ta, sau da yawa ana kiranta main ko master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Rikicin merge","text":"Idan canje-canje biyu sun taɓa layuka iri ɗaya ta hanyoyi daban-daban, don haka kwamfuta ba za ta iya haɗa su ba kuma dole mutum ya zaɓa.","also":["merge conflict","merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"Kallon da ke nuna ainihin abin da ya canza tsakanin sigogi biyu: layukan da aka ƙara da layukan da aka cire.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Kwafin repo na wani naku, wanda za ku iya canzawa ba tare da shafar nasa ba.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"Ƙaramin shiri da ke yin aiki ɗaya da kansa, kamar gyara fayiloli ko fara manhaja.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Mayar da lamba zuwa wani abu da ke shirye don gudana, ko sakamakon da aka shirya kansa.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Fassara lambar da mutane suka rubuta zuwa tsarin da kwamfuta za ta iya gudanarwa kai tsaye.","also":["compiler"]},{"id":"cli","g":"build","word":"Layin umarni (CLI)","text":"Taga ta rubutu inda kuke buga umarni ga kwamfuta maimakon dannawa. Ana kuma kiranta terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Tsari (config)","text":"Saitunan da ke sarrafa yadda software ke aiki, ana ajiye su dabam da lamba don a canja su cikin sauƙi.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"Saiti da ake ba wa shiri idan ya fara, sau da yawa ana amfani da shi don adireshi ko kalmomin sirri don kada a rubuta su a lamba.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Gyaran bug (Debugging)","text":"Neman dalilin da yasa wani abu ba ya aiki, da gyara shi.","also":["debug","debugged","debugging"]},{"id":"pairing","g":"build","word":"Shirya tare biyu (Pair programming)","text":"Mutum biyu (ko mutum da AI) suna aiki a kan lamba ɗaya tare, ɗaya yana rubutawa ɗaya yana dubawa.","also":["pairing","pair programming"]},{"id":"docs","g":"build","word":"Takardun bayani (docs)","text":"Rubutattun bayanai kan yadda wani abu yake aiki ko yadda ake amfani da shi.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Fayil na farko da za a karanta a repo: menene aikin da yadda ake sa shi ya fara aiki.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Tsohon tsari","text":"Tsohon tsarin da har yanzu ake amfani da shi mai wuyar canzawa, sau da yawa saboda mutane kaɗan ne har yanzu suka fahimce shi.","also":["legacy systems","legacy code","legacy system"]},{"id":"techdebt","g":"build","word":"Bashin fasaha","text":"Hanyoyin gajeren hanya da ke adana lokaci yanzu amma suna sa canje-canje daga baya su yi jinkiri, kamar bashi da ke tara riba. Refactoring yana biyan shi.","also":["tech debt","technical debt"]},{"id":"test","g":"test","word":"Gwaji","text":"Binciken cewa wani abu yana aiki yadda ya kamata. Wasu gwaje-gwaje kwamfuta ce ke gudanar da su da kanta duk lokacin da lamba ta canza; wasu kuma ku ne ke gwada kati da aka gama kafin ku karɓe shi.","also":["gwada","gwadawa","gwaje-gwaje","gwajin","test","tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Gajeren suna na quality assurance: duk abin da ake yi don tabbatar da aiki daidai ne kafin ya fita kai tsaye. A AI-gile wannan yana nufin binciken atomatik: idan QA ja ne, wani abu ya faɗi, kuma ba zai iya fita ba sai an gyara hakan.","also":["binciken inganci","quality checks"]},{"id":"testpile","g":"test","word":"Tarin gwaji","text":"Katunan da aka gama da ke jiran ka gwada, ɗaya bayan ɗaya. Karɓi ɗaya ko mayar da shi da bayani, sai na gaba ya bayyana.","also":["test pile"]},{"id":"autotest","g":"test","word":"Gwajin kai-da-kai","text":"Dubawar da kwamfuta ke yi da kanta duk lokacin da lamba ta canza, don kama kurakurai da wuri.","also":["automated tests","automatic tests","automated test"]},{"id":"manualtest","g":"test","word":"Gwajin hannu","text":"Mutum yana gwada aikin da hannu don ganin ko yana aiki yadda ya kamata.","also":["manual tests","manual testing","manual test"]},{"id":"unittest","g":"test","word":"Gwajin unit","text":"Ƙaramin duba ta atomatik na guntun lamba ɗaya shi kaɗai.","also":["unit tests","unit test"]},{"id":"integtest","g":"test","word":"Gwajin haɗin kai","text":"Duba cewa sassa da yawa suna aiki daidai tare, ba ɗaya-ɗaya kaɗai ba.","also":["integration tests","integration test"]},{"id":"endtoend","g":"test","word":"Gwajin daga farko zuwa ƙarshe (E2E)","text":"Gwajin da ke yin kamar ainihin mai amfani daga farko zuwa ƙarshe, kamar yin rajista, siya da biya.","also":["E2E","end-to-end tests","end-to-end test"]},{"id":"uat","g":"test","word":"Gwajin karɓar mai amfani (UAT)","text":"Mutanen da suka nemi aikin su gwada shi da kansu su ce ko yana yin abin da suke buƙata. Tarin gwajin AI-gile shi ne irinsa.","also":["UAT","acceptance testing","user acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Abin da ya yi aiki a da amma ya lalace bayan canji. Gwajin regression yana tabbatar da tsofaffin abubuwa suna nan suna aiki.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Gwajin hayaƙi (Smoke test)","text":"Duba da sauri sosai ko manyan abubuwa suna aiki ko kaɗan, misali nan da nan bayan canji ya fita kai tsaye. Idan ya faɗi, a tsaya a duba.","also":["smoke test","smoke tests"]},{"id":"exploratory","g":"test","word":"Gwajin bincike-bincike","text":"Gwada samfur cikin 'yanci da tsokanar sa ta hanyoyi daban-daban, don nemo matsalolin da binciken da aka tsara zai rasa.","also":["exploratory test","exploratory tests","exploratory testing"]},{"id":"testcase","g":"test","word":"Shari'ar gwaji (Test case)","text":"Yanayi ɗaya rubutacce da za a gwada: matakai, da abin da ya kamata ya faru.","also":["test case","test cases"]},{"id":"coverage","g":"test","word":"Rufin gwaji (Test coverage)","text":"Yawan lambar da gwaje-gwaje na atomatik ke dubawa. Fiye da haka yawanci ya fi tsaro, amma babban rufi kaɗai ba ya tabbatar yana aiki da kyau.","also":["code coverage","test coverage"]},{"id":"testdata","g":"test","word":"Bayanan gwaji","text":"Bayanan misali na ƙirƙira da ake amfani da su yayin gwaji, don kada a bayyana sirrin ainihin wani.","also":["test fixtures","test data"]},{"id":"edgecase","g":"test","word":"Lamarin gefe (Edge case)","text":"Yanayi na ban mamaki a iyakoki, kamar fom ɗin da babu komai ko suna mai alamar apostrophe, inda abubuwa ke yawan lalacewa.","also":["edge cases","edge case"]},{"id":"happypath","g":"test","word":"Hanyar farin ciki (Happy path)","text":"Hanyar al'ada inda komai ke tafiya daidai. Kyakkyawan gwaji yana kuma gwada hanyoyin marasa daɗi."},{"id":"perftest","g":"test","word":"Gwajin aiki (Performance testing)","text":"Duba yadda wani abu yake da sauri da yadda yake jurewa matsi.","also":["performance test","performance tests","performance testing"]},{"id":"loadtest","g":"test","word":"Gwajin nauyi (Load testing)","text":"Duba yadda tsari ke jurewa idan mutane da yawa suna amfani da shi a lokaci ɗaya.","also":["load test","load tests","load testing"]},{"id":"sectest","g":"test","word":"Gwajin tsaro","text":"Neman rauni da zai bar wani ya yi amfani da tsari ta hanyar da ba ta dace ba ko ya ga abin da bai kamata ba.","also":["security test","security tests","security testing"]},{"id":"accesstest","g":"test","word":"Gwajin isa ga kowa","text":"Duba cewa mutanen da ke da iyawa daban-daban za su iya amfani da samfur, har da mai karanta allo ko madannai kaɗai.","also":["accessibility test","accessibility testing"]},{"id":"linting","g":"test","word":"Linting","text":"Binciken atomatik da ke gano kurakurai masu yiwuwa da rashin tsabtar salo a lamba, kamar mai duba rubutun kalmomi na shirye-shirye.","also":["linter","lint","linting"]},{"id":"static","g":"test","word":"Binciken lamba (Static analysis)","text":"Duba lamba don matsaloli ta hanyar karanta ta ta atomatik, ba tare da gudanar da ita ba.","also":["static code analysis","static analysis"]},{"id":"flaky","g":"test","word":"Gwajin mara tabbas","text":"Gwajin da wani lokaci yake wucewa wani lokaci yake faɗuwa ba tare da dalili bayyananne ba, don haka ba za a iya dogara da shi sosai ba.","also":["flaky tests","flaky test"]},{"id":"repro","g":"test","word":"Sake haddasawa (repro)","text":"Sa bug ya sake faruwa da gangan ta bin matakai ɗaya, don a yi nazarin sa a gyara. Rubuta waɗannan matakai shi ne ɓangaren rahoton bug mafi amfani.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Tsananin matsala","text":"Yadda tasirin matsala yake da muni, daga ɗan bacin rai zuwa komai ya tsaya.","also":["severity level","severity"]},{"id":"deploy","g":"change","word":"Deploy","text":"Kwafi sabuwar sigar software zuwa kwamfutocin da ke gudanar da ita, kamar kwafin gwaji ko sabis na kai tsaye."},{"id":"release","g":"change","word":"Sakewa","text":"Tarin aikin da aka gama mai suna wanda ke fita kai tsaye tare, da gajerun bayanai kan abin da ya canza. 🚀 Sakewa na rubuta bayanan daga katunan da aka gama.","also":["sakewa","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Komawa sigar ƙarshe da ta yi aiki idan sabuwa ta kawo matsala. A AI-gile, Roll back yana tattara matakan soke da aka rubuta a kowane canji zuwa jerin dubawa ɗaya.","also":["roll back","mayar da baya"]},{"id":"live","g":"change","word":"Kai tsaye","text":"Ainihin sigar da mutane ke amfani da ita, ba kwafi don gwada abubuwa ba. Masu haɓakawa kuma suna kiranta production.","also":["live","production"],"noTip":1},{"id":"change","g":"change","word":"Canji","text":"Canjin da aka tsara a kan abin da mutane suka dogara da shi, an rubuta shi tukuna: me, me yasa, haɗarin, yaushe, da yadda za a mayar da shi. Fara ɗaya da 🔀 Gabatar da canji.","also":["canje-canje","buƙatar canji","change request"],"noTip":1},{"id":"risk","g":"change","word":"Haɗari","text":"Wani abu da zai iya lalacewa, an ba shi maki gwargwadon yiwuwarsa da girman illarsa. ⚠️ Haɗura na ajiye su a jeri ɗaya, mafi girman maki a farko, kowanne da ranar sake dubawa.","also":["haɗura","rajistar haɗura","risk register"]},{"id":"chgwin","g":"change","word":"Tagar canji","text":"Lokutan da canje-canje za su iya fita kai tsaye, kamar maraicen Talata mai shiru. A wajen taga ba za a iya gama katin canji ba, sai dai idan gaggawa ce.","also":["tagogin canji","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Duba na ƙarshe kafin canji ya fita: kowane mutum da dole ya amince yana cewa Go ko No go. Yana ci gaba ne kawai idan kowa ya ce Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Amincewa","text":"Jiran “eh” kafin aiki ya fara. Katin da aboki ya gabatar, ko canji, yana jira a ✅ Amincewa har sai ka amince ko ka ƙi.","also":["approval","approvals"]},{"id":"quiettime","g":"change","word":"Lokacin shiru","text":"Lokaci kamar lokacin watsa shirye-shirye kai tsaye, demo ko da dare, lokacin da babu abin da ke fita. Ƙungiyoyi suna ci gaba da aiki da gwaji, amma fita yana jira har ya ƙare. A wasu wurare ana kiransa change freeze.","also":["lokutan shiru","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Hanyar aiki inda mutanen da ke gina software da waɗanda ke gudanar da ita suke aiki a matsayin ƙungiya ɗaya, da sarrafa kai da yawa, don canje-canje su fita akai-akai kuma cikin aminci."},{"id":"cicd","g":"change","word":"CI/CD (haɗawa da isarwa ta ci gaba)","text":"Ana haɗa canje-canjen kowa cikin babbar sigar akai-akai a duba su ta atomatik kowane lokaci (continuous integration), don software ta kasance a shirye ta fita a danna maɓalli (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Fitarwa ta ci gaba","text":"Mataki ɗaya gaba da continuous delivery: kowane canji da ya wuce binciken yana fita da kansa, babu maɓallin da za a danna.","also":["continuous deployments","continuous deployment"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Jerin matakai na atomatik da canji ke bi kan hanyarsa zuwa fita, kamar build, gwaji, sannan deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Muhalli (Environment)","text":"Kwafi dabam ɗaya na tsari don manufa ɗaya, kamar ɗaya don gini, ɗaya don gwaji da na kai tsaye.","also":["muhallai","environment","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Muhallin haɓakawa","text":"Kwafin da mai haɓaka ke aiki a ciki, sau da yawa a kwamfutarsa, inda lalata abubuwa ba ya cutar da kowa.","also":["dev environment","development environment"]},{"id":"testenv","g":"change","word":"Muhallin gwaji","text":"Kwafi dabam na tsari da ake amfani da shi don gwaji kawai, don kada a taɓa sabis na gaske.","also":["test environments","test environment"]},{"id":"staging","g":"change","word":"Staging","text":"Kwafin ƙarshe da aka saita kamar na kai tsaye, don binciken ƙarshe kafin canji ya fita.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Abin da build ya samar","text":"Fayil ko tarin da build ke samarwa, a shirye don a adana, a duba ko a fitar.","also":["build artifact","build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Gyara na gaggawa da ake fitarwa da sauri, a wajen shirin al'ada, saboda wani abu mai muhimmanci ya lalace.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"Ƙaramin sabuntawa da ke gyara bug ko rufe ramin tsaro. Shigar da patch na tsaro da sauri yana da muhimmanci.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Lambar sigar","text":"Alamar kamar 2.4.1 da ke cewa wace sakewa kuke da ita. Sau da yawa lamba ta farko tana canjawa don manyan canje-canje ta ƙarshe kuma don ƙananan gyare-gyare.","also":["version numbers","semantic versioning","version number"]},{"id":"relnotes","g":"change","word":"Bayanan sakewa","text":"Gajeren jeri a sarari na abin da ya canza a sakewa, ga mutanen da ke amfani da ita, har da gyare-gyare da iyakokin da aka sani. Ana kuma kiran shi changelog.","also":["changelog","change log","release notes"]},{"id":"flag","g":"change","word":"Feature flag","text":"Maɓallin kunnawa da kashewa don siffa, don sabon aiki ya fita a ɓoye a kunna shi (ko a kashe shi) ba tare da sabon sakewa ba.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Gyara mummunan sakewa ta fitar da sabuwar sigar da aka gyara da sauri maimakon komawa tsohuwa.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Fitar da canji kai tsaye ga ƙaramin rukuni da farko, ga kowa kuma sai idan ya yi kyau. An sa masa suna bayan canaries da masu haƙa ma'adinai suke kai ƙasa a matsayin gargaɗi na farko.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Riƙe kwafi biyu na tsarin kai tsaye a mayar da mutane zuwa sabo gaba ɗaya, don ku iya komawa nan da nan idan an samu matsala.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Fitarwa ba tare da tsayawa ba","text":"Fitar da sabuwar sigar ba tare da sabis ya taɓa tsayawa ga masu amfani da shi ba.","also":["zero downtime","zero-downtime","zero-downtime deployment"]},{"id":"chgenable","g":"change","word":"Sarrafa canji","text":"Taimakawa canje-canje su yi nasara: auna haɗari, samun amincewar da ta dace da zaɓar lokaci mai kyau. Ana kuma kiran shi change management.","also":["change management","change enablement"]},{"id":"cab","g":"change","word":"Kwamitin shawarar canji (CAB)","text":"Ƙungiyar da ke duba muhimman canje-canje ta amince ko kuma lokacin da za su ci gaba.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Canji na yau da kullun","text":"Canji mai ƙarancin haɗari da ake yi ta hanyar da aka gwada iri ɗaya kowane lokaci, don haka an riga an amince da shi.","also":["standard changes","standard change"]},{"id":"normchange","g":"change","word":"Canji na al'ada","text":"Canji da ke buƙatar a duba shi a amince da shi kafin ya ci gaba.","also":["normal changes","normal change"]},{"id":"emergchange","g":"change","word":"Canjin gaggawa","text":"Canji da dole ya faru nan da nan don gyara ko hana babbar matsala, tare da amincewa cikin sauri daidai da haka.","also":["emergency changes","emergency change"]},{"id":"automation","g":"change","word":"Sarrafa kai","text":"Sa kwamfuta ta yi aikin da ake maimaitawa da kanta, don ya fi sauri kuma a yi shi iri ɗaya kowane lokaci.","also":["automated","automation"],"noTip":1},{"id":"infra","g":"change","word":"Kayayyakin more rayuwa (Infrastructure)","text":"Na'urori, hanyoyin sadarwa da sabis ɗin da software ke aiki a kansu.","also":["infra","infrastructure"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Bayyana sabobinku da saitunanku a fayiloli da ake ajiyewa tare da lamba, don a sake gina su iri ɗaya kowane lokaci.","also":["IaC"]},{"id":"cloud","g":"change","word":"Gajimare (Cloud)","text":"Yin hayar kwamfutoci, ajiya da sabis daga babban mai bayarwa ta intanet, maimakon mallakar na'urorin da kanku.","also":["the cloud","cloud computing","cloud"]},{"id":"provider","g":"change","word":"Mai bayar da gajimare","text":"Kamfani da ke ba da hayar kwamfuta ta intanet, kamar Amazon Web Services (AWS), Microsoft Azure ko Google Cloud.","also":["cloud providers","cloud provider"]},{"id":"hosting","g":"change","word":"Hosting","text":"Inda manhajarku ko gidan yanar gizonku ke zaune da gudana don mutane su isa gare shi, yawanci ana yin hayarsa daga kamfani.","also":["hosting"]},{"id":"domain","g":"change","word":"Sunan yanki","text":"Adireshin yanar gizo da mutane ke bugawa, kamar example.com. Kuna yin haya na shekara ɗaya, don haka dole a sabunta.","also":["sunayen yanki","domain name","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Gajeren suna na domain name system: littafin adireshin intanet, wanda ke mayar da suna kamar example.com zuwa adireshin kwamfutar da ta dace.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"Kunshin da aka rufe da ke ɗauke da manhaja da duk abin da take buƙata, don ta yi aiki iri ɗaya a kowace kwamfuta. Docker shi ne kayan aiki mafi sanannu.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Kwamfuta ta ƙirƙira (VM)","text":"Kwamfuta ta riya da ke gudana a cikin ta gaske, don babbar na'ura ɗaya ta yi kama da da yawa.","also":["VM","VMs","virtual machine","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Gudanar da lamba ba tare da kula da wata sabar da kanku ba: mai bayarwa yana gudanar da ita idan ana buƙata kuma kuna biyan abin da kuka yi amfani da shi."},{"id":"lb","g":"change","word":"Mai rarraba nauyi","text":"Wani abu da ke raba baƙi a kan sabobi da yawa, don babu ɗaya da zai cika da yawa.","also":["load balancers","load balancer"]},{"id":"cache","g":"change","word":"Cache","text":"Ma'ajiya mai amfani ta sakamakon baya-bayan nan da ake riƙe kusa, don kada a sake ɗauko ko lissafa abu iri ɗaya. Share ta na iya gyara shafukan da suke kama da tsofaffi.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Hanyar isar da abun ciki (CDN)","text":"Tarin sabobi na duniya da ke riƙe kwafin shafukanku da hotuna kusa da baƙi, don su yi lodi da sauri.","also":["CDN","content delivery network"]},{"id":"migration","g":"change","word":"Ƙaura (Migration)","text":"Mayar da bayanai ko tsare-tsare daga tsohon tsari zuwa sabo, ko canza yadda ake shimfiɗa ma'ajiyar bayanai a hankali.","also":["migrations","database migration","migration"]},{"id":"service","g":"run","word":"Sabis","text":"Abin da ka gina da mutane suka dogara da shi, kamar shafin yanar gizo ko manhaja, ana kula da shi don ya ci gaba da aiki. Yi alama a “Wannan aiki sabis ne” ka faɗi abin da yake bayarwa, wa ke amfani da shi da wa ke kan kira.","also":["sabis-sabis","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Yawan lokacin da sabis ke aiki, yawanci a matsayin kaso. 99.9% har yanzu yana barin kusan minti 43 a kashe a wata.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Binciken uptime","text":"Bincike na atomatik, bayan 'yan mintuna, cewa sabis ɗinka yana amsawa har yanzu. Idan ya gaza sau da yawa a jere, AI-gile zai buɗe katin matsala da kansa.","also":["uptime checks"]},{"id":"statuspage","g":"run","word":"Shafin matsayi","text":"Shafin jama'a da ke nuna ko sabis yana aiki (kore, lemu ko ja) tare da sabon bayani, don mutanen da ke amfani da shi su duba maimakon tambaya.","also":["shafukan matsayi","status page"]},{"id":"desk","g":"run","word":"Teburin sabis","text":"Inda tambayoyi da rahotanni daga mutanen da ke amfani da sabis ɗinka ke shigowa. AI-gile yana tsara kowanne zuwa buƙata, matsala ko ra'ayi, kuma yana faɗa idan ya yi kama da wani abu da aka riga aka ruwaito.","also":["teburan sabis","teburin taimako","help desk"]},{"id":"svcrequest","g":"run","word":"Buƙatar sabis","text":"Wani yana neman abu na yau da kullum, kamar sabon asusu ko ɗan taimako, maimakon ya ruwaito cewa wani abu ya lalace. Tana jiran lokacinta; matsala tana zuwa farko.","also":["buƙatun sabis"]},{"id":"incident","g":"run","word":"Matsala","text":"Wani abu da ya lalace ko ba ya aiki yadda ya kamata ga mutanen da ke amfani da shi yanzu, kamar gidan yanar gizo ya kashe ko yana da jinkiri sosai. Katin matsala 🔥 yana tsallake layi: dawo da shi aiki ne ke zuwa da farko.","also":["matsaloli","incident"]},{"id":"major","g":"run","word":"Babbar matsala","text":"Matsala mai girma sosai: mutane da yawa abin ya shafa, ko kuɗi ko bayanai suna cikin haɗari. Maɓalli ɗaya yana sa dukkan ƙungiyoyi a kanta (swarm), yana tashe duk wanda ke kan kira, kuma yana neman bayanin matsayi kowane mintuna 30.","also":["manyan matsaloli","major incident"]},{"id":"oncall","g":"run","word":"Kan kira","text":"Kasancewa wanda ke amsawa idan wani abu ya lalace, ko da da dare. Kowane sabis yana da memba na ƙungiya a kan kira wanda ake tashe da farko don matsalolinsa.","also":["on call","on-call"]},{"id":"replyby","g":"run","word":"Lokacin amsa","text":"Tsawon lokacin da kati zai iya jira amsa ta farko, misali awa ɗaya don matsala. Bayan haka yana samun agogo ja, don kada a manta da wani abu shiru. Ana kuma kiransa burin amsa.","also":["lokutan amsa","burin amsa","response target"]},{"id":"postmortem","g":"run","word":"Bita bayan matsala","text":"Ɗan duba baya bayan matsala: abin da ya faru, abin da ya taimaka da abin da za a canza, ba tare da zargin kowa ba. Ba za a iya rufe matsala ba sai da ita.","also":["post-mortem","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Matsala mai maimaituwa","text":"Ɓoyayyen dalili a bayan matsala ɗaya ko fiye. Katin 🧩 matsala mai maimaituwa yana tara matsalolin da ke ta dawowa, don a gano dalilin a gyara shi har abada.","also":["problem","matsalar tushe"],"noTip":1},{"id":"rootcause","g":"run","word":"Tushen dalili","text":"Ainihin dalilin da ya sa wani abu ya lalace, ba kawai abin da ka ga ya ɓaci ba. Gyara tushen dalilin, matsalar za ta daina dawowa.","also":["tushen matsala","root cause"]},{"id":"workaround","g":"run","word":"Mafita na ɗan lokaci","text":"Hanyar sa abubuwa su ci gaba da aiki har ainihin gyaran ya shirya, kamar sake kunna wani abu idan ya makale. Ana rubuta ta a katin matsala mai maimaituwa don kada wani ya sake nemo ta.","also":["hanyar wucin gadi","workaround"]},{"id":"knownerror","g":"run","word":"Kuskuren da aka sani","text":"Matsala da aka fahimci dalilinta amma ba a gyara ba tukuna, yawanci tare da hanyar wucin gadi da aka rubuta. 🧩 Matsalolin da aka sani suna jera su, don kowa ya yi amfani da hanyar wucin gadi maimakon sake bincike.","also":["kurakuran da aka sani","known error"]},{"id":"runbook","g":"run","word":"Littafin aiki","text":"Umarnin mataki-mataki don gyara wani irin matsalar da aka sani, don a yi ta hanya ɗaya, cikin sauri, kowane lokaci. Bayan babbar matsala ƙungiyar za ta iya ba da shawarar ɗaya don ka ba da OK.","also":["runbook","runbooks"]},{"id":"ci","g":"run","word":"Abin tsari","text":"Abu ɗaya da sabis ɗinka ya dogara a kai, kamar sabar, sunan yanki, takardar shaida, maɓalli ko mai kawowa. 🗂️ Abubuwan tsari na jera su ga kowane sabis, don ka ga abin da matsala take shafa da abin da ke buƙatar sabuntawa ko ajiyar tsaro.","also":["abubuwan tsari","configuration item"]},{"id":"expiry","g":"run","word":"Ranar ƙarewa","text":"Ranar da wani abu ke daina aiki sai an sabunta shi, kamar takardar tsaro ta gidan yanar gizo ko adireshinsa. AI-gile yana kallon waɗannan ranaku yana yin kati ɗaya na sabuntawa ga kowanne kwana 30 kafin, don babu abin da ya tsaya ba zato ba tsammani.","also":["ranakun ƙarewa","ƙarewa","sa ido kan ƙarewa"]},{"id":"backup","g":"run","word":"Ajiyar tsaro","text":"Kwafin bayananka da aka ajiye tun da, don a koma gare shi idan wani abu ya ɓace ko ya lalace. AI-gile na yin ajiyar tsaro na allunanka kowace rana.","also":["backup","backups"]},{"id":"restore","g":"run","word":"Maido","text":"Mayar da bayanai daga ajiyar tsaro. Ajiyar tsaro tana da amfani da gaske ne kawai idan ka san za a iya maido ta, don haka yana da kyau a gwada lokaci-lokaci.","also":["maidowa","restore"]},{"id":"svcreview","g":"run","word":"Bitar sabis","text":"Waiwaye kan wata ɗaya na sabis: matsalolin da aka buɗe da aka gyara, yadda mutane suka sami amsa da sauri, uptime da tokens da aka yi amfani da su. Bitar wata tana nuna shi ga kowane sabis.","also":["bitocin sabis","bitar wata","bitocin wata"]},{"id":"accessreview","g":"run","word":"Duba samun dama","text":"Duba kowane kwana 90 wanda har yanzu zai iya shiga: hanyoyin haɗin raba, matsayin abokai da kalmomin sirri da maɓallan da aka adana. Kuna riƙe ko cire kowanne, don tsohuwar dama kada ta rage.","also":["binciken samun dama","access review"]},{"id":"improvements","g":"run","word":"Jerin ingantawa","text":"Duk abin da ƙungiyar ta yanke shawarar ingantawa, a wuri ɗaya: shawarwarin retro, ayyukan bita da gyaran matsaloli, kowanne da matsayinsa. Za ka same shi a ƙarƙashin 📈 Ingantawa.","also":["jerin ingantawa","ingantawa"]},{"id":"tokencap","g":"run","word":"Iyakar tokens","text":"Iyakar wata-wata kan tokens da wakilan sabis za su iya amfani da su. A 80% za ka sami gargaɗi; a 100% aikinsu na bayan fage yana jira har wata mai zuwa ko har sai ka ɗaga iyakar.","also":["iyakokin tokens","token cap"]},{"id":"svcmgmt","g":"run","word":"Sarrafa sabis","text":"Duk abin da ke ciki na kiyaye sabis mai amfani kuma yana aiki ga mutanen da suka dogara da shi, rana bayan rana.","also":["service management"]},{"id":"itil","g":"run","word":"ITIL","text":"Jagorar da ake amfani da shi sosai don kyakkyawan sarrafa sabis, wanda ya ƙunshi abubuwa kamar matsaloli, tushen matsaloli da canje-canje. Sunan a da yana nufin IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Sarrafa sabis na IT (ITSM)","text":"Gudanar da fasaha a matsayin sabis ga mutane, da hanyoyi bayyanannu na magance buƙatu, matsaloli, canje-canje da ingantawa.","also":["ITSM","IT service management"]},{"id":"managed","g":"run","word":"Sabis da ake sarrafawa","text":"Sabis da wani ke gudanarwa yana kula da shi a madadinku, bisa yarjejeniya kan yadda dole ya yi aiki.","also":["managed services","managed service"]},{"id":"svcowner","g":"run","word":"Mai sabis","text":"Wanda ke da alhakin sabis gaba ɗaya: yadda yake aiki da kyau, abin da yake kashewa da yadda yake inganta.","also":["service owners","service owner"]},{"id":"sla","g":"run","word":"Yarjejeniyar matakin sabis (SLA)","text":"Alkawari a rubuce ga abokan ciniki kan yadda sabis zai yi aiki, kamar “a kunne 99.9% na lokaci” ko “a amsa cikin sa'a ɗaya”, sau da yawa da mayar da kuɗi idan an karya shi.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Burin matakin sabis (SLO)","text":"Burin ƙungiya kanta na yadda sabis ya kamata ya yi aiki a wani lokaci, yawanci ana saita shi ɗan tsauri fiye da SLA don aminci.","also":["SLO","SLOs","service level objective"]},{"id":"sli","g":"run","word":"Alamar matakin sabis (SLI)","text":"Ainihin ma'aunin da kuke dubawa a kan buri, kamar kaso na ziyarar da suka yi lodi da kyau.","also":["SLI","SLIs","service level indicator"]},{"id":"availability","g":"run","word":"Samuwa (Availability)","text":"Ko mutane za su iya amfani da sabis idan suna buƙata, sau da yawa ana auna shi a matsayin uptime.","also":["high availability","availability"]},{"id":"downtime","g":"run","word":"Lokacin kashewa (Downtime)","text":"Lokacin da sabis ba ya aiki ko aka kashe shi, an tsara shi ko ba a tsara ba.","also":["down time","downtime"]},{"id":"errorbudget","g":"run","word":"Kasafin kuskure (Error budget)","text":"Ƙaramin adadin gazawa da burin amincinku ya yarda da shi. Matuƙar akwai saura za ku iya yin kasada da canje-canje; idan ya ƙare, sai ku rage gudu.","also":["error budgets","error budget"]},{"id":"outage","g":"run","word":"Katsewa (Outage)","text":"Lokacin da sabis ya ƙare ko ya lalace sosai ga masu amfani da shi.","also":["outages","outage"]},{"id":"degraded","g":"run","word":"Raguwar aiki (Degraded)","text":"Yana aiki, amma ba daidai ba: a hankali, ko wasu sassa ba sa aiki.","also":["degraded service","degraded"]},{"id":"monitoring","g":"run","word":"Sa ido (Monitoring)","text":"Kallon sabis ta atomatik a kowane lokaci, don a gano matsaloli, zai fi kyau kafin masu amfani su lura.","also":["monitoring"]},{"id":"observability","g":"run","word":"Observability","text":"Yadda za ku iya gane abin da ke faruwa a cikin tsari daga waje, ta amfani da logs, lambobi da traces ɗinsa.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"Littafin yau da kullun da shiri ke ajiyewa na abin da yake yi, ana amfani da shi don gano abin da ya yi kuskure.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"Bayanin yadda buƙata ɗaya ke tafiya ta sassa daban-daban na tsari, mataki-mataki, yana nuna inda ta yi jinkiri.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Jinkiri (Latency)","text":"Tsawon lokacin da wani abu ke ɗauka kafin ya amsa, kamar jira tsakanin dannawa da shafin ya bayyana.","also":["latency"]},{"id":"alert","g":"run","word":"Faɗakarwa (Alert)","text":"Saƙon atomatik cewa wani abu yana buƙatar kulawa, kamar gidan yanar gizo ba ya amsawa.","also":["alerts","alerting","alert"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Gajiya da faɗakarwa","text":"Idan faɗakarwa sun yi yawa har mutane suka fara yin watsi da su, har da masu muhimmanci.","also":["alarm fatigue","alert fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"Allo da ke nuna muhimman lambobi da matsayi a kallo ɗaya.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Kiran gaggawa (Paging)","text":"Kira ko tada mai aiki a kan-kira da gaggawa game da matsala.","also":["paged","paging"]},{"id":"escalation","g":"run","word":"Ɗaga matsala (Escalation)","text":"Kawo wanda ke da ƙarin ƙwarewa ko iko idan ba za a iya warware matsala a matakin yanzu ba, ko ba da sauri ba.","also":["escalate","escalated","escalation"]},{"id":"triage","g":"run","word":"Triage","text":"Rarraba matsaloli masu shigowa da sauri bisa gaggawa da muhimmanci, don mafi muni a magance shi da farko.","also":["triaged"]},{"id":"impact","g":"run","word":"Tasiri (Impact)","text":"Yadda wani abu ke shafar mutane: nawa, da yadda yake da muni.","noTip":1},{"id":"urgency","g":"run","word":"Gaggawa (Urgency)","text":"Yadda da sauri ake buƙatar magance wani abu. Tasiri da gaggawa tare suke saita fifiko.","noTip":1},{"id":"plevels","g":"run","word":"Matakan fifiko (P1, P2…)","text":"Alamomi na yadda matsala take da gaggawa. P1 ita ce mafi tsanani kuma tana buƙatar aiki nan da nan.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Jerin tikiti","text":"Jerin buƙatu da matsalolin da ke jiran a ɗauka.","also":["ticket queue","ticket queues"]},{"id":"tiers","g":"run","word":"Layi na farko da na biyu","text":"Matakan tallafi: layi na farko yana karɓar kira yana gyara abubuwa masu sauƙi; layi na biyu yana da zurfin ƙwarewa ga masu wahala. Ana kuma kiransu tier 1 da tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Kwamandan matsala (Incident commander)","text":"Mutum ɗaya da ke jagorantar amsa ga matsala, don kowa ya san wanda ke yanke shawara da wanda ke yin me.","also":["incident commander","incident commanders"]},{"id":"responsetime","g":"run","word":"Lokacin amsawa","text":"Tsawon lokacin da ake ɗauka kafin wani ya fara ɗaukar buƙata ko matsala.","also":["response time","response times"]},{"id":"resolution","g":"run","word":"Lokacin warwarewa","text":"Tsawon lokacin da ake ɗauka don warware buƙata ko matsala gaba ɗaya, daga rahoto zuwa gyarawa.","also":["resolution time","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Matsakaicin lokacin murmurewa (MTTR)","text":"A matsakaici, tsawon lokacin da ake ɗauka don mayar da sabis aiki bayan ya lalace. MTTR na iya nufin abubuwa daban kaɗan, don haka a faɗi abin da kuke aunawa.","also":["MTTR","mean time to restore","mean time to recover"]},{"id":"mtbf","g":"run","word":"Matsakaicin lokaci tsakanin gazawa (MTBF)","text":"A matsakaici, tsawon lokacin da sabis ke gudana kafin wani abu ya lalace.","also":["MTBF","mean time between failures"]},{"id":"cmdb","g":"run","word":"Ma'ajiyar tsarin kayayyaki (CMDB)","text":"Jerin dukan abubuwan tsarinku da yadda suke haɗe, don ku ga abin da ke dogara da me.","also":["CMDB","configuration management database"]},{"id":"asset","g":"run","word":"Kadara (Asset)","text":"Duk wani abu mai daraja da kuke mallaka ko kuke biya don gudanar da sabis, kamar kwamfutar riga, lasisin software ko sunan yanki.","also":["kadarori","asset","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Tsara ƙarfin aiki","text":"Tabbatar da cewa za a sami isasshen ƙarfin kwamfuta, ajiya da mutane don abin da ke zuwa.","also":["capacity plan","capacity planning"]},{"id":"scaling","g":"run","word":"Faɗaɗawa (Scaling)","text":"Jure wa ƙarin masu amfani ta ba wa na'ura ƙarin ƙarfi (scaling up) ko ƙara na'urori (scaling out).","also":["scale up","scale out","scaling up","scaling out","scaling"]},{"id":"bcp","g":"run","word":"Ci gaba da kasuwanci","text":"Tsare-tsare don ci gaba da muhimman abubuwa idan wani babban abu ya lalace, kamar rasa ofis, mai kawo kaya mai muhimmanci ko kwamfutoci.","also":["business continuity","business continuity plan"]},{"id":"dr","g":"run","word":"Murmurewa daga bala'i (DR)","text":"Shirin da kayan aiki don dawo da sabis bayan wani babban abu, kamar rasa cibiyar bayanai gaba ɗaya.","also":["disaster recovery","DR"]},{"id":"rto","g":"run","word":"Burin lokacin murmurewa (RTO)","text":"Mafi tsawon lokacin da sabis zai iya kasancewa a kashe bayan bala'i kafin dole ya sake aiki.","also":["RTO","recovery time objective"]},{"id":"rpo","g":"run","word":"Burin wurin murmurewa (RPO)","text":"Nawa na sabbin bayanai za ku iya iya rasawa, a auna cikin lokaci. RPO na sa'a ɗaya yana nufin ajiyar tsaro aƙalla kowace sa'a.","also":["RPO","recovery point objective"]},{"id":"redundancy","g":"run","word":"Ƙarin kayan jira (Redundancy)","text":"Samun kayan jira a shirye, kamar sabar ta biyu, don gazawa ɗaya ba ta tsayar da sabis ba.","also":["redundancy"]},{"id":"failover","g":"run","word":"Failover","text":"Mayewa zuwa tsarin jira da kansa idan na yau da kullun ya faɗi.","also":["fail over"]},{"id":"spof","g":"run","word":"Wuri guda na gazawa","text":"Sashe ɗaya da ke rushe komai tare da shi idan ya lalace, saboda babu kayan jira.","also":["single point of failure","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Tagar gyara","text":"Lokacin da aka tsara inda sabis zai iya tsayawa ko yin jinkiri don kulawa, ana sanar da masu amfani tun da wuri.","also":["maintenance window","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Miƙa aiki (Handover)","text":"Miƙa aiki, ilimi da alhaki ga wani mutum ko ƙungiya, don kada wani abu ya ɓace.","also":["handover","handovers"]},{"id":"kb","g":"run","word":"Ma'ajiyar ilimi (Knowledge base)","text":"Tarin labaran taimako da amsoshi, ga masu amfani da ga ƙungiya.","also":["knowledge base","knowledge bases"]},{"id":"csat","g":"run","word":"Gamsuwar abokin ciniki (CSAT)","text":"Maki daga masu amfani da ke cewa yadda suka yi farin ciki, sau da yawa ana tambaya bayan an rufe buƙata.","also":["CSAT","customer satisfaction"]},{"id":"supplier","g":"run","word":"Mai kawo kaya","text":"Kamfani na waje da kuka dogara da shi, kamar mai ba da hosting ɗinku. Ana kuma kiransa vendor ko third party.","also":["masu kawo kaya","supplier","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Daina sabis","text":"Kashe sabis har abada, cikin aminci: sanar da masu amfani da shi, magance bayanansa da isarsa, da dakatar da kuɗin da yake kashewa.","also":["retiring a service","service retirement"]},{"id":"eol","g":"run","word":"Ƙarshen rayuwa (EOL)","text":"Idan samfur ya daina karɓar sabuntawa ko tallafi daga mai yin sa, don haka ya kamata a maye gurbinsa.","also":["EOL","end-of-life","end of life"]},{"id":"cybersec","g":"sec","word":"Tsaron intanet","text":"Kare tsare-tsare da bayanai daga a fasa, a sace ko a lalata su.","also":["cybersecurity","cyber security"]},{"id":"authn","g":"sec","word":"Tabbatar da ainihi (Authentication)","text":"Duba wanene wani, yawanci da kalmar sirri ko lamba. Ana gajarta shi sau da yawa zuwa authn.","also":["authn","authentication"]},{"id":"authz","g":"sec","word":"Ba da izini (Authorisation)","text":"Duba abin da aka ba wani izini ya yi bayan an san wanene shi. Ana gajarta shi sau da yawa zuwa authz.","also":["authz","authorization","authorisation"]},{"id":"mfa","g":"sec","word":"Tabbatarwa ta matakai da yawa (MFA)","text":"Shiga da shaidu biyu ko fiye, kamar kalmar sirri da lamba a wayarku. Ana kuma kiran sa two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication","multi-factor authentication"]},{"id":"sso","g":"sec","word":"Shiga sau ɗaya (SSO)","text":"Shiga sau ɗaya don shiga tsare-tsare da yawa, kamar amfani da asusunku na aiki a ko'ina.","also":["SSO","single sign-on"]},{"id":"pwmgr","g":"sec","word":"Mai sarrafa kalmomin sirri","text":"Manhaja da ke ƙirƙirar kalmomin sirri masu ƙarfi tana tuna muku su.","also":["password manager","password managers"]},{"id":"secret","g":"sec","word":"Sirri (Secret)","text":"Kalmar sirri, maɓalli ko wata lamba ta sirri da shiri ke amfani da ita don shiga wani abu. Kada a taɓa raba ta ko a rubuta ta a lamba.","also":["secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Maɓallin API","text":"Lambar sirri da ke bari shiri ya yi amfani da API na wani sabis, tana nuna wanda ke amfani da shi (kuma yake biyan sa).","also":["API key","API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"Izinin wucin gadi da ke tabbatar da cewa shiri yana da izinin shiga, don kada a buƙaci kalmar sirrinku kowane lokaci. Ba daidai yake da token na AI ba.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Boye bayanai (Encryption)","text":"Ruɗe bayanai don kawai wanda ke da maɓalli daidai ne zai iya karanta su.","also":["encrypted","encrypt","encryption"]},{"id":"https","g":"sec","word":"HTTPS","text":"Hanya mai tsaro da shafukan yanar gizo ke tafiya, wadda makullin da ke burauzarku ke nunawa, don babu wanda ke tsakani da zai iya karanta su ko canza su."},{"id":"cert","g":"sec","word":"Takardar shaidar SSL/TLS","text":"Katin shaida na dijital da ke bari gidan yanar gizo ya tabbatar da ko wanene shi ya yi amfani da HTTPS. Yana ƙarewa, don haka dole a sabunta shi.","also":["TLS certificate","SSL certificate","certificate","certificates","SSL/TLS certificate"]},{"id":"permissions","g":"sec","word":"Izini","text":"Ƙa'idojin wanda zai iya gani ko canza me.","also":["permission","permissions"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Mafi ƙarancin dama","text":"Ba wa kowane mutum ko shiri damar da suke buƙata kawai, na tsawon lokacin da suke buƙata kawai.","also":["principle of least privilege","least privilege"]},{"id":"rbac","g":"sec","word":"Samun dama bisa matsayi (RBAC)","text":"Ba da dama bisa matsayi, kamar mai kallo ko mai gyara, maimakon mutum bayan mutum.","also":["RBAC","role-based access","role-based access control"]},{"id":"vuln","g":"sec","word":"Rauni (Vulnerability)","text":"Rauni da wani zai iya amfani da shi ya shiga ko ya yi lahani.","also":["vulnerabilities","vulnerability"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Rauni da maharan suka sani kafin masu yin sa su sami wani lokaci na gyarawa.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Software mai cutarwa, kamar ƙwayoyin cuta, da aka yi don lalata, leƙen asiri ko sata."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware da ke kulle fayilolinku tana neman kuɗi kafin a buɗe su. Kyawawan ajiyar tsaro su ne mafi kyawun kariya.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Saƙonnin ƙarya da ke ƙoƙarin yaudarar ku ku ba da kalmomin sirri ko kuɗi, ko ku buɗe wani abu mai cutarwa.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Yaudarar mutane (Social engineering)","text":"Yaudarar mutane, ba kwamfutoci ba, don ba da dama, kamar kiran ƙarya daga “tallafin IT”."},{"id":"firewall","g":"sec","word":"Firewall","text":"Mai tsaro da ke yanke shawarar wace zirga-zirgar hanyar sadarwa za ta shigo ko ta fita.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Gajeren suna na virtual private network: hanya ta sirri, ruɗaɗɗiya ta intanet, ana amfani da ita sau da yawa don isa ga tsare-tsaren aiki cikin aminci.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Hana sabis (DoS, DDoS)","text":"Cika sabis da zirga-zirgar ƙarya mai yawa har mutane na gaske ba za su iya amfani da shi ba. DDoS yana nufin yana zuwa daga kwamfutoci da yawa a lokaci ɗaya.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Gwajin kutsawa (pen test)","text":"Ɗaukar ƙwararru abokan hulɗa su yi ƙoƙarin kutsawa, don a gano raunuka kafin maharan gaske su gano su.","also":["pen test","pen testing","penetration testing","pentest","penetration test"]},{"id":"audit","g":"sec","word":"Binciken tsaro","text":"Bincike mai kyau na yadda ake kare wani abu, bisa jerin kyawawan ayyuka.","also":["security audit","security audits"]},{"id":"threatmodel","g":"sec","word":"Tsara kariya daga barazana","text":"Tunani kan wanda zai iya kai hari ga wani abu, ta yaya, da abin da za ku yi don hana su.","also":["threat model","threat modeling","threat modelling"]},{"id":"breach","g":"sec","word":"Fallasar bayanai","text":"Idan bayanan sirri suka fita zuwa ga mutanen da bai kamata su same su ba, ko aka rasa ko aka canza su ba tare da izini ba.","also":["data breach","data breaches"]},{"id":"pii","g":"sec","word":"Bayanan sirri na mutum","text":"Duk wani bayani game da mutumin da za a iya gane shi, kamar suna, adireshin imel ko wuri. Ana kuma kiran sa PII.","also":["PII","personally identifiable information","personal data"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Dokar Turai kan bayanan sirri (Birtaniya tana da nata): a tara abin da kuke buƙata kawai, a kiyaye shi lafiya, kuma a bar mutane su ga ko su share nasu.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Kare bayanai","text":"Kula da bayanan sirri yadda ya kamata da bisa doka.","also":["data protection","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Manufar sirri","text":"Shafi na jama'a da ke cewa wane bayanan sirri kuke tarawa, don me, da abin da kuke yi da su.","also":["privacy policy","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Izini na sani","text":"Eh ɗin mutum a sarari kuma ba tilas ba don a yi amfani da bayanansa ta wata hanya. Zai iya janye shi a kowane lokaci.","also":["opt-in","consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Ƙaramin fayil da gidan yanar gizo ke adanawa a burauzarku don tunawa da abubuwa, kamar kasancewa a shiga. Wasu suna buƙatar izininku da farko.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Rage tarin bayanai","text":"Tarawa da riƙe bayanan sirrin da kuke buƙata sosai don aikin kawai.","also":["data minimisation","data minimization"]},{"id":"retention","g":"sec","word":"Tsawon riƙe bayanai","text":"Tsawon lokacin da ake riƙe bayanai kafin a share su. Riƙe su ba tsawon da ake buƙata ba ya fi aminci kuma sau da yawa doka ce.","also":["data retention","retention period"]},{"id":"anon","g":"sec","word":"Rufe ainihi (Anonymisation)","text":"Canza bayanai don babu wanda za a iya gane shi daga cikinsu da hankali kuma.","also":["anonymised","anonymization","anonymous data","anonymisation"]},{"id":"pseudo","g":"sec","word":"Maye gurbin suna (Pseudonymisation)","text":"Maye gurbin sunaye da sauran bayanai da lambobi, tare da maɓalli da aka ajiye dabam don mayar da su. Har yanzu bayanan sirri ne.","also":["pseudonymised","pseudonymization","pseudonymisation"]},{"id":"dpa","g":"sec","word":"Yarjejeniyar sarrafa bayanai (DPA)","text":"Kwangila da ke cewa yadda mai kawo kaya zai iya sarrafa bayanan sirri a madadinku.","also":["DPA","data processing agreement"]},{"id":"dpia","g":"sec","word":"Kimanta tasirin kare bayanai (DPIA)","text":"Dubawa mai zurfi, kafin ku fara, na yadda shirin amfani da bayanan sirri zai iya shafar mutane da yadda za a rage haɗarin.","also":["DPIA","data protection impact assessment"]},{"id":"auditlog","g":"sec","word":"Rajistar bincike (Audit log)","text":"Rikodin wanda ya yi me da lokacin da, don a iya duba ayyuka daga baya.","also":["audit log","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Bin ƙa'ida (Compliance)","text":"Bin dokoki, ƙa'idoji da ma'auni da suka shafe ku, da iya nuna cewa kuna yi.","also":["compliant","compliance"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Sanannen ma'aunin ƙasa da ƙasa don sarrafa tsaron bayanai. Kamfanoni za su iya samun takardar shaida a kansa.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Rahoton Amurka, wanda masu bincike na waje suka duba, yana nuna kamfani yana kula da bayanan abokan ciniki yadda ya kamata.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Wakili","text":"AI da ke aiki a kan ɗawainiya da kansa: yana karanta lamba, yana yin canje-canje, yana gudanar da bincike yana ba da rahoto. Har yanzu ana duba aikinsa.","also":["agents","wakilai","agent"]},{"id":"token","g":"ai","word":"Token","text":"Ƙananan guntayen rubutu da AI ke karantawa yana rubutawa, kusan kashi uku cikin huɗu na kalma kowanne. Ana ƙidaya amfani da AI a tokens, don haka ƙananan tokens suna barin ƙarin tsarinku.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Ƙaramin umarni da ke gudana da kansa a wani lokaci kayyadadde, misali idan zaman AI ya fara, don ƙungiya ta ji sharhinku.","also":["hooks"]},{"id":"ai","g":"ai","word":"Hankali na wucin gadi (AI)","text":"Tsare-tsaren kwamfuta da ke yin abubuwan da yawanci muke tsammanin mutum ne ke bukata, kamar rubutu, amsa tambayoyi ko gane hotuna.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Koyon na'ura (ML)","text":"Hanyar sa kwamfutoci su koyi tsari daga misalai da yawa, maimakon a ba su ainihin ƙa'idoji.","also":["ML","machine learning"]},{"id":"model","g":"ai","word":"Model","text":"“Kwakwalwar” da aka horar ta tsarin AI, wadda aka gina ta koyo daga misalai masu yawa. Models sun bambanta a ƙwarewa, gudu da farashi.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Babban samfurin harshe (LLM)","text":"Samfurin AI da aka horar da shi a kan rubutu mai yawa, don ya iya karantawa da rubuta harshe.","also":["LLM","LLMs","large language model"]},{"id":"genai","g":"ai","word":"AI mai ƙirƙira (Generative AI)","text":"AI da ke ƙirƙirar sababbin abubuwa, kamar rubutu, hotuna ko lamba, ba kawai rarraba ko gano su ba.","also":["GenAI","generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Shirin da kuke magana da shi da harshen yau da kullun, ta rubutu ko magana.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Abin da kuke ba AI: tambayarku ko umarninku, da duk abin da kuka ba shi. Prompts masu fayyace yawanci suna samun mafi kyawun amsoshi.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Rubuta prompt (Prompt engineering)","text":"Ƙwarewar rubuta prompts da ke samar da sakamako abin dogaro, mai amfani.","also":["prompt engineering"]},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Umarni na bayan fage da AI ke samu kafin tattaunawa ta fara, yana saita matsayinsa da ƙa'idojinsa. Suna da nauyi fiye da abin da kuke bugawa.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Mahallin (Context)","text":"Duk abin da AI zai iya gani yayin da yake aiki: umarni, saƙonninku, fayilolin da ya karanta da amsoshin da suka gabata.","noTip":1},{"id":"ctxwin","g":"ai","word":"Taga mahallin (Context window)","text":"Nawa AI zai iya riƙewa a zuciya a lokaci ɗaya, ana aunawa da tokens. Fiye da haka, tsofaffin ɓangarori ana watsar da su ko a taƙaita su.","also":["context window","context windows"]},{"id":"session","g":"ai","word":"Zama (Session)","text":"Tattaunawa ɗaya ta aiki da AI, daga farko zuwa ƙarshe. Sabon zama yana farawa da sabon ƙwaƙwalwa.","also":["zama","session","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Ƙwaƙwalwa","text":"Bayanan da AI ke ajiyewa tsakanin zama, don ya tuna abubuwan da kuka fi so da shawarwarin da suka gabata.","noTip":1},{"id":"hallucination","g":"ai","word":"Ƙirƙirar ƙarya (Hallucination)","text":"Idan AI ya faɗi wani abu da yake kama da tabbaci amma ƙirƙira ne ko kuskure. A duba muhimman bayanai.","also":["hallucinations","hallucinate","hallucinates","hallucination"]},{"id":"training","g":"ai","word":"Horarwa (Training)","text":"Koya wa model ta nuna masa misalai masu yawa, kafin kowa ya yi amfani da shi.","also":["trained","training"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Bayanan horarwa","text":"Misalan da model ya koya daga gare su. Iliminsa yana tsayawa a ranar da aka tara bayanan.","also":["training set","training data"]},{"id":"cutoff","g":"ai","word":"Ranar ƙarshen ilimi","text":"Ranar da ilimin da AI ke da shi ya ƙare. Ba zai san abubuwan da suka biyo baya ba sai ya nema su.","also":["training cutoff","knowledge cutoff"]},{"id":"finetune","g":"ai","word":"Daidaita model (Fine-tuning)","text":"Ƙarin horar da model da ke akwai a kan misalanku, don ya fi iyawa a aiki ɗaya na musamman.","also":["fine-tune","fine-tuned","fine tuning","fine-tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"Ana amfani da model na AI da gaske don amsa wani abu, sabanin horar da shi.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Amfani da kayan aiki (Tool use)","text":"AI yana iya yin abubuwa, ba kawai magana ba: gudanar da umarni, karanta fayiloli ko neman yanar gizo, ta kayan aikin da manhaja ta ba shi.","also":["tool calling","tool call","tool calls","tool use"]},{"id":"subagent","g":"ai","word":"Mataimakin wakili (Subagent)","text":"Mataimakin AI da babban AI ke ba wa ƙaramin aiki, yana karɓar sakamako daga gare shi.","also":["subagents","sub-agent","subagent"]},{"id":"multiagent","g":"ai","word":"Wakilai da yawa (Multi-agent)","text":"AI da yawa suna aiki tare a kan guntun aiki ɗaya, kowanne da nasa ɓangaren, kamar ƙaramar ƙungiya.","also":["multi-agent","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Cin gashin kai (Autonomy)","text":"Nawa AI zai iya yi shi kaɗai kafin dole ya tambayi mutum.","also":["autonomous","autonomy"]},{"id":"hitl","g":"ai","word":"Mutum a cikin zagaye","text":"Riƙe mutum a ciki don ya duba ko ya amince da abin da AI ke yi a muhimman lokuta. A AI-gile wannan kai ne.","also":["human in the loop","human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Shingen tsaro (Guardrails)","text":"Iyakoki da bincike da ke kiyaye ayyukan AI lafiya, kamar buƙatar amincewa kafin wani abu ya fita. Suna rage haɗarin kurakurai, amma ba sa kawar da su gaba ɗaya.","also":["guardrail","guardrails"]},{"id":"rag","g":"ai","word":"Samarwa mai taimakon bincike (RAG)","text":"Bar AI ya nemi abubuwa a takardunku kafin ya amsa, don amsoshinsa su kasance bisa gaskiyarku.","also":["RAG","retrieval augmented generation","retrieval-augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Mayar da rubutu zuwa jerin lambobi da ke ɗauke da ma'anarsa, don kwamfuta ta nemo abubuwan da ma'anarsu iri ɗaya ce.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Ma'ajiyar vector","text":"Ma'ajiyar bayanai da aka gina don neman waɗannan jerin lambobi (embeddings), don samo abu mai ma'ana iri ɗaya.","also":["vector database","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Hanyar gama-gari ta haɗa kayan aiki da hanyoyin bayanai cikin manhajojin AI, don AI ya iya amfani da su.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Zafi (Temperature)","text":"Saiti na yadda amsoshin AI suke da ƙarfin hali. Ƙasa yana ba da amsoshi masu tsayayye, masu hasashe; sama yana ba da bambance-bambance. Babu ɗayansu da ke sa shi daidai koyaushe.","also":["temperature","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Mai iya aiki da fiye da nau'in bayani ɗaya, kamar rubutu, hotuna da sauti.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Kimantawa (eval)","text":"Gwajin da aka tsara na yadda AI ke yi a kan misalan da aka zaɓa, don a kwatanta models ko prompts.","also":["eval","evals","evaluation"]},{"id":"bias","g":"ai","word":"Son zuciya (Bias)","text":"Idan AI (ko mutum) ya karkata ba daidai ba ta wani gefe, sau da yawa saboda abin da ya koya daga gare shi.","also":["biased","bias"],"noTip":1},{"id":"responsible","g":"ai","word":"AI mai alhaki","text":"Amfani da AI cikin adalci, aminci da gaskiya, tare da mutane har yanzu suna da alhakin sakamakon.","also":["ethical AI","responsible AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Dabarar da umarni na ɓoye a shafin yanar gizo ko fayil ke ƙoƙarin sa AI ya yi abin da mai amfani da shi bai nema ba.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Iyakar buƙata (Rate limit)","text":"Iyaka kan buƙatu nawa za ku iya aika wa sabis a wani lokaci. Idan kun wuce, dole ku jira.","also":["rate limit","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Iyakar amfani (Usage limit)","text":"Nawa na aikin AI tsarinku ya yarda a wani lokaci, bayan haka yana tsayawa ko ya fi tsada.","also":["usage limit","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Gina software galibi ta bayyana wa AI abin da kuke so a bar shi ya rubuta lamba.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Kasafin kuɗi","text":"Adadin kuɗin da aka ware don wani abu.","also":["budgets","budget"],"noTip":1},{"id":"costest","g":"money","word":"Ƙiyasin farashi","text":"Mafi kyawun zato na abin da wani abu zai kashe kafin ku fara.","also":["cost estimate","cost estimates"]},{"id":"roi","g":"money","word":"Dawowar jari (ROI)","text":"Abin da kuke samu idan aka kwatanta da abin da kuka saka. Idan yana da kyau, ya cancanta.","also":["ROI","return on investment"]},{"id":"tco","g":"money","word":"Jimillar farashin mallaka (TCO)","text":"Duk abin da wani abu ke kashewa a rayuwarsa gaba ɗaya, ba kawai farashin siye ba: gudanarwa, tallafi, ingantawa da ƙarshe yin ritaya da shi.","also":["TCO","total cost of ownership"]},{"id":"capex","g":"money","word":"CapEx da OpEx","text":"CapEx kuɗi ne da ake kashewa tun da farko kan abubuwan da kuke riƙewa; OpEx kashe kuɗi ne mai ci gaba, kamar kuɗin wata-wata.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Biyan kuɗin wata-wata (Subscription)","text":"Biyan kuɗi akai-akai, yawanci wata ko shekara, don ci gaba da amfani da wani abu.","also":["subscriptions","subscription"],"noTip":1},{"id":"saas","g":"money","word":"Software a matsayin sabis (SaaS)","text":"Software da kuke amfani da ita a kan layi kuna biya da biyan kuɗi na lokaci, yayin da mai yin ta ke gudanar da ita muku.","also":["SaaS","software as a service"]},{"id":"payg","g":"money","word":"Biyan abin da aka yi amfani da shi","text":"Biyan abin da kuka yi amfani da shi kawai, kamar gajimare ko tokens na AI.","also":["pay as you go","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Ƙari fiye da iyaka (Overage)","text":"Amfani fiye da abin da tsarinku ya haɗa, wanda zai iya kashe ƙarin kuɗi.","also":["overage","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Faɗakarwar lissafi","text":"Saƙo idan kashe kuɗi ko amfani ya kai matakin da kuka zaɓa. Yana gargaɗin ku, amma ba koyaushe yake dakatar da ƙarin cajin ba.","also":["billing alert","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Matakin kyauta","text":"Matakin kyauta na sabis mai biya, da iyakoki. Yana da amfani don farawa.","also":["free tier","free plan"]},{"id":"pricing","g":"money","word":"Tsarin farashi","text":"Fakitin daban-daban da sabis ke sayarwa, kowanne da nasa farashi da iyakoki.","also":["pricing plan","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Lasisi","text":"Ƙa'idojin yadda za ku iya amfani da, kwafi, canza ko raba abin da wani ya yi, kamar software, nau'in rubutu ko hotuna.","also":["licences","license","licenses","licence"],"noTip":1},{"id":"opensource","g":"money","word":"Buɗaɗɗen tushe (Open source)","text":"Software da kowa zai iya karanta lambarta, ya yi amfani da ita kuma sau da yawa ya canza ta kyauta, bisa ƙa'idojin lasisinta.","also":["open source","open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Lasisin buɗaɗɗen tushe","text":"Ƙa'idojin da ke zuwa da lambar buɗaɗɗen tushe. Wasu suna barin ku yin kusan komai (kamar MIT); wasu suna neman ku raba canje-canjenku ma (kamar GPL).","also":["open source licence","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Mallakar kamfani (Proprietary)","text":"Kamfani ne ya mallake shi ba a yarda a kwafe ko a canza shi kyauta ba. Akasin buɗaɗɗen tushe.","also":["proprietary","proprietary software"]},{"id":"copyright","g":"money","word":"Haƙƙin mallaka (Copyright)","text":"Haƙƙin doka na mai ƙirƙira na sarrafa kwafin aikinsa, har da lamba da rubutu.","also":["copyrighted","copyright"],"noTip":1},{"id":"ip","g":"money","word":"Mallakar ƙwaƙwalwa (IP)","text":"Ra'ayoyi da ƙirƙire-ƙirƙire da doka ke ɗauka a matsayin abin da aka mallaka, kamar lamba, ƙira, sunaye da tambura.","also":["IP","intellectual property"]},{"id":"tos","g":"money","word":"Sharuɗɗan sabis","text":"Ƙa'idojin da kuke yarda da su idan kuka yi amfani da sabis.","also":["terms and conditions","terms of use","sharuɗɗan amfani","terms of service"]},{"id":"contract","g":"money","word":"Kwangila","text":"Yarjejeniyar rubutu tsakanin ɓangarori biyu da doka za ta goyi bayanta.","also":["kwangiloli","contract","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Bayanin aiki (SOW)","text":"Takarda da ke bayyana daidai aikin da za a yi, zuwa yaushe da kuma nawa ne.","also":["SOW","statement of work"]},{"id":"fixedprice","g":"money","word":"Farashi tabbatacce","text":"Farashin da aka amince da shi ga duka aikin, ko da tsawon lokacin da ya ɗauka.","also":["fixed price","fixed-price"]},{"id":"tm","g":"money","word":"Lokaci da kayayyaki","text":"Biyan sa'o'in da aka yi aiki da gaske da abubuwan da aka yi amfani da su da gaske, maimakon farashi kayyadadde.","also":["T&M","time and materials"]},{"id":"invoice","g":"money","word":"Takardar kuɗi (invoice)","text":"Takardar neman biyan aikin da aka yi ko kayan da aka kawo.","also":["invoice","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Ɗaurin mai kawo kaya","text":"Idan barin mai kawo kaya yana da wahala ko tsada har ku makale da shi.","also":["lock-in","vendor lock-in"]},{"id":"procurement","g":"money","word":"Sayen kaya (Procurement)","text":"Tsarin zaɓa da siya daga masu kawo kaya.","also":["procurement"]},{"id":"servicecredit","g":"money","word":"Kuɗin diyyar sabis","text":"Kuɗin da ake mayarwa ko rangwamen da kuke samu idan mai kawo kaya ya kasa cika SLA ɗinsa.","also":["service credit","service credits"]}]}};
